export const c12Phy6HtmlOverview = "\n<style>\n  p, li, div:not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n  \n  <!-- QUICK GLOSSARY CARD -->\n  <div style=\"background: rgba(255, 82, 82, 0.05); border: 1.5px solid #FF5252; border-radius: 12px; padding: 18px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #FF5252; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">📖 Quick Glossary &amp; Basic Definitions</h2>\n    <p class=\"text-center\" style=\"color: #FF5252; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Essential Core Concepts &amp; Key Definitions &bull; Unit VI: Optics (Ray &amp; Wave Optics)</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF5252; border-radius: 6px;\">\n        <b style='color: #FF5252; display: block; margin-bottom: 4px;'>1. Refractive Index (&mu; / n):</b>\n        <span style=\"color: #FFFFFF;\">Ratio of speed of light in vacuum to speed in medium: &mu; = c/v = sin i / sin r [Dimensionless [M<sup>0</sup> L<sup>0</sup> T<sup>0</sup>]].</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF5252; border-radius: 6px;\">\n        <b style='color: #FF5252; display: block; margin-bottom: 4px;'>2. Critical Angle (i<sub>c</sub>):</b>\n        <span style=\"color: #FFFFFF;\">Angle of incidence in denser medium for which angle of refraction in rarer medium is 90&deg;: sin i<sub>c</sub> = 1/&mu; = &mu;<sub>rarer</sub>/&mu;<sub>denser</sub> [Degrees/Radians].</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF5252; border-radius: 6px;\">\n        <b style='color: #FF5252; display: block; margin-bottom: 4px;'>3. Power of a Lens (P):</b>\n        <span style=\"color: #FFFFFF;\">Ability of a lens to converge or diverge incident light rays, defined as reciprocal of focal length in meters: P = 1/f(m) [Dioptre D = m<sup>-1</sup>, [M<sup>0</sup> L<sup>-1</sup> T<sup>0</sup>]].</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF5252; border-radius: 6px;\">\n        <b style='color: #FF5252; display: block; margin-bottom: 4px;'>4. Wavefront:</b>\n        <span style=\"color: #FFFFFF;\">Continuous locus of all medium particles oscillating in the exact same phase. Light rays are always normal to the wavefront at every point.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF5252; border-radius: 6px;\">\n        <b style='color: #FF5252; display: block; margin-bottom: 4px;'>5. Coherent Sources:</b>\n        <span style=\"color: #FFFFFF;\">Two light sources emitting waves of identical frequency, wavelength, and constant or zero initial phase difference (&Delta;&phi; = const).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF5252; border-radius: 6px;\">\n        <b style='color: #FF5252; display: block; margin-bottom: 4px;'>6. Fringe Width (&beta;):</b>\n        <span style=\"color: #FFFFFF;\">Separation between two consecutive bright or dark interference fringes in Young's double slit experiment: &beta; = &lambda; D / d [Meter m, [M<sup>0</sup> L<sup>1</sup> T<sup>0</sup>]].</span>\n      </div>\n    </div>\n  </div>\n<h2 style=\"color: #FF5252; border-bottom: 2px solid #FF5252; padding-bottom: 6px; margin-top: 25px;\">PART I: Ray Optics &amp; Optical Instruments</h2>\n<h2 style=\"color: #FF5252; margin-top: 25px;\">1. Reflection of Light, Spherical Mirrors &amp; Mirror Formula</h2>\n<h3 style=\"color: #FF5252; margin-top: 20px;\">(i) Laws of Reflection &amp; Sign Convention</h3>\n<p>Light travels along straight lines (rectilinear propagation) in a homogeneous medium. When light encounters a polished surface, it bounces back according to two fundamental laws:</p>\n  <ul>\n    <li>1. The incident ray, reflected ray, and normal to the reflecting surface at the point of incidence all lie in the <b>same plane</b>.</li>\n    <li>2. The angle of incidence equals the angle of reflection: <b>&angle;i = &angle;r</b>.</li>\n  </ul>\n  <p><b>New Cartesian Sign Convention:</b></p>\n  <ul>\n    <li>• All optical distances are measured from the <b>Pole (P)</b> of the mirror along the principal axis.</li>\n    <li>• Distances measured in the direction of incident light are taken as <b>Positive (+)</b>; distances against incident light are <b>Negative (-)</b>.</li>\n    <li>• Heights measured upward perpendicular to the principal axis are <b>Positive (+)</b>; downward heights are <b>Negative (-)</b>.</li>\n    <li>• <i>Result:</i> Focal length of concave mirror is <b>negative (f &lt; 0)</b>; focal length of convex mirror is <b>positive (f &gt; 0)</b>.</li>\n  </ul>\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 82, 82, 0.4); border-radius: 10px; padding: 14px 16px; margin: 18px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 440px;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Diagram 1: Reflection of Light &amp; Spherical Mirrors\" style=\"max-width: 100%; height: auto; display: block; border-radius: 6px; object-fit: contain;\" />\n    </div>\n    <p style=\"color: #94A3B8; font-size: 13.5px; line-height: 1.5; margin: 10px 0 0 0; text-align: center !important;\"><b>Fig 6.1:</b> Ray Tracing for Spherical Mirrors &ndash; Real inverted image formation in a Concave mirror (Focus F, Center of Curvature C, Focal length f), Virtual erect image in a Convex mirror, and the Mirror Formula (1/f = 1/v + 1/u).</p>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 82, 82, 0.5); border-radius: 8px; padding: 16px 20px; margin: 18px 0;\">\n    <div style=\"color: #FF5252; font-size: 16.5px; font-weight: bold; margin-bottom: 10px; border-bottom: 1px solid rgba(255, 82, 82, 0.3); padding-bottom: 6px;\">📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Mirror Formula for a Concave Mirror (Real Image)</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.75;\">\n    <b>Step 1 (Geometry of Triangles):</b> Consider an object AB placed beyond Center of Curvature C of a concave mirror of small aperture. Light from A strikes pole P and reflects forming real inverted image A'B'.<br>\n    From similar right-angled triangles &Delta;ABP and &Delta;A'B'P:<br>\n    <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">A'B'</span><span style=\"padding: 0 2px; display: inline-block;\">AB</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">PB'</span><span style=\"padding: 0 2px; display: inline-block;\">PB</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">-v</span><span style=\"padding: 0 2px; display: inline-block;\">-u</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v</span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span>. &nbsp;&nbsp; ...(1)<br>\n    <b>Step 2 (Triangles through Center of Curvature C):</b> From similar triangles &Delta;ABC and &Delta;A'B'C:<br>\n    <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">A'B'</span><span style=\"padding: 0 2px; display: inline-block;\">AB</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">CB'</span><span style=\"padding: 0 2px; display: inline-block;\">BC</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">PC - PB'</span><span style=\"padding: 0 2px; display: inline-block;\">PB - PC</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">-R - (-v)</span><span style=\"padding: 0 2px; display: inline-block;\">-u - (-R)</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">-R + v</span><span style=\"padding: 0 2px; display: inline-block;\">-u + R</span></span>. &nbsp;&nbsp; ...(2)<br>\n    <b>Step 3 (Equating &amp; Rearranging):</b> Equating (1) and (2):<br>\n    <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v</span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">-R + v</span><span style=\"padding: 0 2px; display: inline-block;\">-u + R</span></span> &rArr; -u v + v R = -u R + u v &rArr; (u + v) R = 2 u v.<br>\n    <b>Step 4 (Substituting R = 2f &amp; Dividing by uvf):</b><br>\n    (u + v)(2f) = 2 u v &rArr; u f + v f = u v.<br>\n    Dividing both sides by (u v f):<br>\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 16.5px;\"><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">f</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span></b></span>.<br>\n    <b>Linear Magnification:</b> <span style=\"color: #00E5FF; font-family: monospace; font-size: 16px;\"><b>m = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h<sub>i</sub></span><span style=\"padding: 0 2px; display: inline-block;\">h<sub>o</sub></span></span> = - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v</span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f</span><span style=\"padding: 0 2px; display: inline-block;\">f - u</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f - v</span><span style=\"padding: 0 2px; display: inline-block;\">f</span></span></b></span>.\n  </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 82, 82, 0.4); border-left: 5px solid #FF5252; border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"color: #FF5252; font-size: 16px; font-weight: bold; margin-bottom: 4px;\">📖 DEFINITION: Mirror Formula (1/f = 1/v + 1/u)</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6; margin-bottom: 8px;\">Fundamental mathematical relationship connecting object distance (u), image distance (v), and focal length (f) of a spherical mirror.</div>\n    <div style=\"display: flex; flex-wrap: wrap; gap: 16px; font-size: 13.5px; background: rgba(0,0,0,0.3); padding: 8px 12px; border-radius: 6px;\">\n      <span style=\"color: #94A3B8;\"><b>SI Unit:</b> <span style=\"color: #FFFFFF;\">Dimensionless (f in meters)</span></span>\n      <span style=\"color: #94A3B8;\"><b>Dimension:</b> <span style=\"color: #FFFFFF;\">[M<sup>0</sup> L<sup>-1</sup> T<sup>0</sup>]</span></span>\n    </div>\n  </div>\n<h2 style=\"color: #FF5252; margin-top: 35px;\">2. Refraction of Light, Total Internal Reflection (TIR) &amp; Optical Fibers</h2>\n<h3 style=\"color: #FF5252; margin-top: 20px;\">(i) Snell's Law &amp; Refractive Index</h3>\n<p>Refraction is the phenomenon of bending of light ray from its original path when it travels obliquely from one transparent medium to another of different optical density, caused by change in speed of light.</p>\n  <div style=\"background: rgba(0,0,0,0.3); border-left: 4px solid #76FF03; padding: 12px 16px; border-radius: 6px; margin: 14px 0;\">\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\"><b>Snell's Law: <sup>1</sup>&mu;<sub>2</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">sin i</span><span style=\"padding: 0 2px; display: inline-block;\">sin r</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">v<sub>2</sub></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&lambda;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">&lambda;<sub>2</sub></span></span></b></span>\n  </div>\n  <p><b>Important Optical Invariant:</b> When light passes from one medium to another, its <b>frequency (&nu;) remains strictly constant</b>, while its velocity (v) and wavelength (&lambda;) change: v = &nu; &lambda;.</p>\n  <div style=\"background: rgba(30, 41, 59, 0.7); border: 1.2px dashed #FFAB91; border-radius: 8px; padding: 12px 16px; margin: 14px 0;\">\n    <div style=\"color: #FFAB91; font-size: 15px; font-weight: bold; margin-bottom: 4px;\">💡 REAL-WORLD INTUITION: Refraction as a Lawn Mower Entering Mud Obliquely</div>\n    <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6;\">Imagine a lawn mower rolling smoothly across concrete onto a muddy lawn at an angle. The first wheel that hits the mud slows down immediately, while the other wheel on the concrete continues at full speed. This speed difference pivots the mower, bending its direction toward the normal! Light bends when entering a denser medium because light wavefronts slow down upon entering.</div>\n  </div>\n<h3 style=\"color: #FF5252; margin-top: 25px;\">(ii) Total Internal Reflection (TIR) &amp; Critical Angle</h3>\n<p>When light travels from an optically <b>denser medium (&mu;<sub>1</sub>)</b> to a <b>rarer medium (&mu;<sub>2</sub>)</b>, the refracted ray bends away from normal (r &gt; i). As angle of incidence i increases, r increases until at a critical angle i<sub>c</sub>, r = 90&deg;. For any angle of incidence i &gt; i<sub>c</sub>, the light ray is 100% internally reflected back into the denser medium!</p>\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 82, 82, 0.4); border-radius: 10px; padding: 14px 16px; margin: 18px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 440px;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Diagram 2: Refraction, Prism Dispersion &amp; Total Internal Reflection in Optical Fibers\" style=\"max-width: 100%; height: auto; display: block; border-radius: 6px; object-fit: contain;\" />\n    </div>\n    <p style=\"color: #94A3B8; font-size: 13.5px; line-height: 1.5; margin: 10px 0 0 0; text-align: center !important;\"><b>Fig 6.2:</b> Refraction and TIR &ndash; Dispersion through prism, TIR at glass-air boundary, and continuous total internal reflection inside an Optical Fiber (high refractive index Core surrounded by lower refractive index Cladding).</p>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 82, 82, 0.5); border-radius: 8px; padding: 16px 20px; margin: 18px 0;\">\n    <div style=\"color: #FF5252; font-size: 16.5px; font-weight: bold; margin-bottom: 10px; border-bottom: 1px solid rgba(255, 82, 82, 0.3); padding-bottom: 6px;\">📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Critical Angle &amp; Refractive Index Relation</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.75;\">\n    Applying Snell's Law at the interface for i = i<sub>c</sub> and r = 90&deg;:<br>\n    &mu;<sub>1</sub> sin(i<sub>c</sub>) = &mu;<sub>2</sub> sin(90&deg;) = &mu;<sub>2</sub> (1).<br>\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\"><b>sin(i<sub>c</sub>) = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span></span></b></span>.<br>\n    For denser medium to air (&mu;<sub>1</sub> = &mu;, &mu;<sub>2</sub> = 1):<br>\n    <span style=\"color: #00E5FF; font-family: monospace; font-size: 16.5px;\"><b>&mu; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">sin i<sub>c</sub></span></span> &nbsp;&hArr;&nbsp; i<sub>c</sub> = sin<sup>-1</sup>(<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">&mu;</span></span>)</b></span>.<br>\n    <i>Key Values:</i> Water (i<sub>c</sub> = 48.75&deg;, &mu; = 1.33), Crown glass (i<sub>c</sub> &approx; 41.1&deg;, &mu; = 1.5), Diamond (i<sub>c</sub> &approx; 24.4&deg;, &mu; = 2.42).\n  </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 82, 82, 0.4); border-left: 5px solid #FF5252; border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"color: #FF5252; font-size: 16px; font-weight: bold; margin-bottom: 4px;\">📖 DEFINITION: Total Internal Reflection (TIR) (i > i_c)</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6; margin-bottom: 8px;\">Phenomenon in which a ray of light traveling from an optically denser to a rarer medium is completely reflected back into the denser medium when angle of incidence exceeds the critical angle.</div>\n    <div style=\"display: flex; flex-wrap: wrap; gap: 16px; font-size: 13.5px; background: rgba(0,0,0,0.3); padding: 8px 12px; border-radius: 6px;\">\n      <span style=\"color: #94A3B8;\"><b>SI Unit:</b> <span style=\"color: #FFFFFF;\">No Unit</span></span>\n      <span style=\"color: #94A3B8;\"><b>Dimension:</b> <span style=\"color: #FFFFFF;\">[M<sup>0</sup> L<sup>0</sup> T<sup>0</sup>]</span></span>\n    </div>\n  </div>\n<h2 style=\"color: #FF5252; margin-top: 35px;\">3. Refraction at Spherical Surfaces, Lenses &amp; Lens Maker's Formula</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 82, 82, 0.5); border-radius: 8px; padding: 16px 20px; margin: 18px 0;\">\n    <div style=\"color: #FF5252; font-size: 16.5px; font-weight: bold; margin-bottom: 10px; border-bottom: 1px solid rgba(255, 82, 82, 0.3); padding-bottom: 6px;\">📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Refraction at a Single Spherical Curved Surface (Convex Surface)</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.75;\">\n    <b>Step 1 (Geometry &amp; Exterior Angle Theorem):</b> Consider a convex spherical surface of radius of curvature R separating medium 1 (&mu;<sub>1</sub>) and medium 2 (&mu;<sub>2</sub>). Point object O is placed on principal axis. Ray OM hits surface at M at angle i and refracts to I at angle r. C is center of curvature.<br>\n    Let &alpha;, &beta;, &gamma; be angles subtended by OM, MI, MC with principal axis:<br>\n    i = &alpha; + &gamma;, &nbsp;&nbsp; &gamma; = r + &beta; &rArr; r = &gamma; - &beta;.<br>\n    <b>Step 2 (Small Angles Approximation tan &theta; &approx; &theta;):</b><br>\n    For paraxial rays: &alpha; &approx; tan &alpha; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">MP</span><span style=\"padding: 0 2px; display: inline-block;\">-u</span></span>, &nbsp; &beta; &approx; tan &beta; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">MP</span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span>, &nbsp; &gamma; &approx; tan &gamma; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">MP</span><span style=\"padding: 0 2px; display: inline-block;\">R</span></span>.<br>\n    <b>Step 3 (Snell's Law for Small Angles):</b> &mu;<sub>1</sub> i = &mu;<sub>2</sub> r.<br>\n    &mu;<sub>1</sub> (&alpha; + &gamma;) = &mu;<sub>2</sub> (&gamma; - &beta;) &rArr; &mu;<sub>1</sub> &alpha; + &mu;<sub>2</sub> &beta; = (&mu;<sub>2</sub> - &mu;<sub>1</sub>) &gamma;.<br>\n    <b>Step 4 (Substituting Angle Expressions):</b><br>\n    &mu;<sub>1</sub> [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">MP</span><span style=\"padding: 0 2px; display: inline-block;\">-u</span></span>] + &mu;<sub>2</sub> [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">MP</span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span>] = (&mu;<sub>2</sub> - &mu;<sub>1</sub>) [<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">MP</span><span style=\"padding: 0 2px; display: inline-block;\">R</span></span>].<br>\n    Canceling MP from both sides gives the Master Curved Surface Formula:<br>\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 16.5px;\"><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub> - &mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">R</span></span></b></span>.\n  </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 82, 82, 0.5); border-radius: 8px; padding: 16px 20px; margin: 18px 0;\">\n    <div style=\"color: #FF5252; font-size: 16.5px; font-weight: bold; margin-bottom: 10px; border-bottom: 1px solid rgba(255, 82, 82, 0.3); padding-bottom: 6px;\">📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Lens Maker's Formula for a Thin Convex Lens</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.75;\">\n    <b>Step 1 (First Surface Refraction at Surface 1 of Radius R<sub>1</sub>):</b><br>\n    Medium outside is &mu;<sub>1</sub> and lens material is &mu;<sub>2</sub>. Ray from object O at distance u forms intermediate virtual image I' at distance v':<br>\n    <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">v'</span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub> - &mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>1</sub></span></span>. &nbsp;&nbsp; ...(1)<br>\n    <b>Step 2 (Second Surface Refraction at Surface 2 of Radius R<sub>2</sub>):</b><br>\n    The intermediate image I' acts as virtual object for surface 2 (traveling from &mu;<sub>2</sub> to &mu;<sub>1</sub>) forming final image at distance v:<br>\n    <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">v'</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub> - &mu;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>2</sub></span></span> = - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub> - &mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>2</sub></span></span>. &nbsp;&nbsp; ...(2)<br>\n    <b>Step 3 (Adding Equations 1 and 2):</b><br>\n    <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span> = (&mu;<sub>2</sub> - &mu;<sub>1</sub>) [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>1</sub></span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>2</sub></span></span> ].<br>\n    Dividing both sides by &mu;<sub>1</sub>:<br>\n    <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span> = (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span></span> - 1) [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>1</sub></span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>2</sub></span></span> ].<br>\n    <b>Step 4 (Using Thin Lens Formula 1/f = 1/v - 1/u):</b><br>\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 16.5px;\"><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">f</span></span> = (&mu; - 1) [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>1</sub></span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>2</sub></span></span> ]</b></span> (where &mu; = &mu;<sub>2</sub>/&mu;<sub>1</sub>).\n  </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 82, 82, 0.4); border-radius: 10px; padding: 14px 16px; margin: 18px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 440px;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Diagram 3: Refraction Through Lenses &amp; Lens Maker's Formula\" style=\"max-width: 100%; height: auto; display: block; border-radius: 6px; object-fit: contain;\" />\n    </div>\n    <p style=\"color: #94A3B8; font-size: 13.5px; line-height: 1.5; margin: 10px 0 0 0; text-align: center !important;\"><b>Fig 6.3:</b> Lenses &ndash; Convergence of parallel incident rays to focus F by a Bi-convex lens, divergence by a Bi-concave lens, and the Lens Maker's Formula: 1/f = (n - 1)(1/R<sub>1</sub> - 1/R<sub>2</sub>).</p>\n  </div>\n<h3 style=\"color: #FF5252; margin-top: 25px;\">(iv) Thin Lens Formula, Power of Lens &amp; Combinations</h3>\n<ul>\n    <li>• <b>Thin Lens Formula:</b> <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\"><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">f</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span></b></span></li>\n    <li>• <b>Linear Magnification:</b> <span style=\"color: #00E5FF; font-family: monospace; font-size: 16px;\"><b>m = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">h<sub>i</sub></span><span style=\"padding: 0 2px; display: inline-block;\">h<sub>o</sub></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v</span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f</span><span style=\"padding: 0 2px; display: inline-block;\">f + u</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f - v</span><span style=\"padding: 0 2px; display: inline-block;\">f</span></span></b></span></li>\n    <li>• <b>Power of a Lens:</b> <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\"><b>P = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">f(m)</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">100</span><span style=\"padding: 0 2px; display: inline-block;\">f(cm)</span></span></b></span> [Dioptres D]. Converging lens: P &gt; 0; Diverging lens: P &lt; 0.</li>\n    <li>• <b>Combination of Thin Lenses in Contact:</b> Equivalent focal length F and total power P:<br>\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\"><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">F</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>1</sub></span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>2</sub></span></span> + ... &nbsp;&hArr;&nbsp; P = P<sub>1</sub> + P<sub>2</sub> + ...</b></span><br>\n    Total magnification is multiplicative: <b>m = m<sub>1</sub> &times; m<sub>2</sub> &times; ...</b></li>\n  </ul>\n  <div style=\"background: rgba(220, 38, 38, 0.1); border: 1.2px solid rgba(239, 68, 68, 0.4); border-left: 5px solid #EF4444; border-radius: 8px; padding: 12px 16px; margin: 14px 0;\">\n    <div style=\"color: #F87171; font-size: 15px; font-weight: bold; margin-bottom: 4px;\">⚠️ BOARD EXAM TRAP &amp; CONCEPTUAL PITFALL: What Happens to a Glass Convex Lens Submerged in Water?</div>\n    <div style=\"color: #FCA5A5; font-size: 14.5px; line-height: 1.6;\">A convex glass lens (&mu;<sub>g</sub> = 1.5) in air has focal length f<sub>a</sub>. When immersed in water (&mu;<sub>w</sub> = 1.33), relative refractive index drops to &mu; = 1.5/1.33 = 1.125. Since (&mu; - 1) decreases by a factor of 4, the focal length increases 4 times: <b>f<sub>water</sub> &approx; 4 f<sub>air</sub></b> and its converging power decreases drastically!</div>\n  </div>\n<h2 style=\"color: #FF5252; margin-top: 35px;\">4. Refraction of Light Through a Triangular Prism &amp; Prism Formula</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 82, 82, 0.5); border-radius: 8px; padding: 16px 20px; margin: 18px 0;\">\n    <div style=\"color: #FF5252; font-size: 16.5px; font-weight: bold; margin-bottom: 10px; border-bottom: 1px solid rgba(255, 82, 82, 0.3); padding-bottom: 6px;\">📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Prism Formula &amp; Angle of Minimum Deviation (D_m)</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.75;\">\n    <b>Step 1 (Angle of Deviation &amp; Geometry):</b> For a triangular glass prism of refracting angle A, a light ray enters at angle i<sub>1</sub>, refracts inside at angle r<sub>1</sub>, hits second face at angle r<sub>2</sub>, and emerges at angle i<sub>2</sub> (or e):<br>\n    In &Delta;QNR: &angle;A + &angle;QNR = 180&deg; and r<sub>1</sub> + r<sub>2</sub> + &angle;QNR = 180&deg; &rArr; <span style=\"color: #00E5FF;\"><b>A = r<sub>1</sub> + r<sub>2</sub></b></span>.<br>\n    Total deviation angle D = (i<sub>1</sub> - r<sub>1</sub>) + (i<sub>2</sub> - r<sub>2</sub>) = (i<sub>1</sub> + i<sub>2</sub>) - (r<sub>1</sub> + r<sub>2</sub>) &rArr; <span style=\"color: #00E5FF;\"><b>D = i + e - A</b></span>.<br>\n    <b>Step 2 (Condition for Minimum Deviation D = D<sub>m</sub>):</b><br>\n    At minimum deviation D = D<sub>m</sub>, the refracted ray passes symmetrically parallel to the base of the prism:<br>\n    i<sub>1</sub> = i<sub>2</sub> = i &nbsp;&nbsp; and &nbsp;&nbsp; r<sub>1</sub> = r<sub>2</sub> = r.<br>\n    Then: A = r + r = 2r &rArr; <span style=\"color: #76FF03;\"><b>r = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">A</span><span style=\"padding: 0 2px; display: inline-block;\">2</span></span></b></span>.<br>\n    And: D<sub>m</sub> = i + i - A = 2i - A &rArr; <span style=\"color: #76FF03;\"><b>i = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">A + D<sub>m</sub></span><span style=\"padding: 0 2px; display: inline-block;\">2</span></span></b></span>.<br>\n    <b>Step 3 (Applying Snell's Law &mu; = sin i / sin r):</b><br>\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b>&mu; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">sin [ (A + D<sub>m</sub>) / 2 ]</span><span style=\"padding: 0 2px; display: inline-block;\">sin (A / 2)</span></span></b></span>.<br>\n    <b>Small-Angle Thin Prism (A &le; 10&deg;):</b> For small angles, sin &theta; &approx; &theta; &rArr; &mu; &approx; <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">(A + D) / 2</span><span style=\"padding: 0 2px; display: inline-block;\">A / 2</span></span> &rArr; <span style=\"color: #00E5FF;\"><b>D = (&mu; - 1) A</b></span>.\n  </div>\n  </div>\n<h2 style=\"color: #FF5252; margin-top: 35px;\">5. Optical Instruments: Microscopes &amp; Astronomical Telescopes</h2>\n<h3 style=\"color: #FF5252; margin-top: 20px;\">(i) Simple Microscope (Magnifying Glass)</h3>\n<p>A simple microscope is a single converging lens of short focal length f. The object is placed within the focal point (u &lt; f) to form an erect, magnified, virtual image.</p>\n  <ul>\n    <li>• <b>Image at Least Distance of Distinct Vision (D = 25 cm):</b> <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\"><b>m = 1 + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">D</span><span style=\"padding: 0 2px; display: inline-block;\">f</span></span></b></span></li>\n    <li>• <b>Image at Infinity (Normal Adjustment / Relaxed Eye):</b> <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\"><b>m = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">D</span><span style=\"padding: 0 2px; display: inline-block;\">f</span></span></b></span></li>\n  </ul>\n<h3 style=\"color: #FF5252; margin-top: 25px;\">(ii) Compound Microscope &amp; Astronomical Telescope</h3>\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 82, 82, 0.4); border-radius: 10px; padding: 14px 16px; margin: 18px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 440px;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Diagram 4: Optical Instruments (Compound Microscope &amp; Astronomical Telescope)\" style=\"max-width: 100%; height: auto; display: block; border-radius: 6px; object-fit: contain;\" />\n    </div>\n    <p style=\"color: #94A3B8; font-size: 13.5px; line-height: 1.5; margin: 10px 0 0 0; text-align: center !important;\"><b>Fig 6.4:</b> Optical Instruments &ndash; Compound Microscope (Eyepiece, Objective lenses, Stage) for high-magnification viewing of micro-specimens, and an Astronomical Telescope (Primary paraboloidal mirror, Secondary mirror, Eyepiece) for distant celestial observation.</p>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 82, 82, 0.5); border-radius: 8px; padding: 16px 20px; margin: 18px 0;\">\n    <div style=\"color: #FF5252; font-size: 16.5px; font-weight: bold; margin-bottom: 10px; border-bottom: 1px solid rgba(255, 82, 82, 0.3); padding-bottom: 6px;\">📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Magnifying Power of a Compound Microscope</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.75;\">\n    <b>Step 1 (Total Angular Magnification):</b> m = m<sub>objective</sub> &times; m<sub>eyepiece</sub> = (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>o</sub></span><span style=\"padding: 0 2px; display: inline-block;\">-u<sub>o</sub></span></span>) &times; m<sub>e</sub>.<br>\n    <b>Case 1 (Final Image at Near Point D = 25 cm):</b><br>\n    m<sub>e</sub> = 1 + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">D</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span> &rArr; <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\"><b>m = - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>o</sub></span><span style=\"padding: 0 2px; display: inline-block;\">u<sub>o</sub></span></span> [ 1 + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">D</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span> ] &approx; - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>o</sub></span></span> [ 1 + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">D</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span> ]</b></span>.<br>\n    Length of microscope tube: <b>L = v<sub>o</sub> + |u<sub>e</sub>|</b>.<br>\n    <b>Case 2 (Final Image at Infinity / Normal Adjustment):</b><br>\n    m<sub>e</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">D</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span> &rArr; <span style=\"color: #00E5FF; font-family: monospace; font-size: 16px;\"><b>m = - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>o</sub></span><span style=\"padding: 0 2px; display: inline-block;\">u<sub>o</sub></span></span> (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">D</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span>) &approx; - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>o</sub></span></span> (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">D</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span>)</b></span>.<br>\n    Tube length in normal adjustment: <b>L = v<sub>o</sub> + f<sub>e</sub></b>.\n  </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 82, 82, 0.5); border-radius: 8px; padding: 16px 20px; margin: 18px 0;\">\n    <div style=\"color: #FF5252; font-size: 16.5px; font-weight: bold; margin-bottom: 10px; border-bottom: 1px solid rgba(255, 82, 82, 0.3); padding-bottom: 6px;\">📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Magnifying Power of Astronomical Refracting Telescope</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.75;\">\n    <b>Case 1 (Normal Adjustment - Final Image at Infinity):</b><br>\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 16.5px;\"><b>m = - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f<sub>o</sub></span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span></b></span>, &nbsp;&nbsp; Length of telescope: <span style=\"color: #76FF03; font-family: monospace; font-size: 16.5px;\"><b>L = f<sub>o</sub> + f<sub>e</sub></b></span>.<br>\n    <b>Case 2 (Final Image at Near Point D = 25 cm):</b><br>\n    <span style=\"color: #00E5FF; font-family: monospace; font-size: 16px;\"><b>m = - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f<sub>o</sub></span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span> [ 1 + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f<sub>e</sub></span><span style=\"padding: 0 2px; display: inline-block;\">D</span></span> ]</b></span>, &nbsp;&nbsp; Length of telescope: <b>L = f<sub>o</sub> + |u<sub>e</sub>|</b>.\n  </div>\n  </div>\n<h2 style=\"color: #FF5252; border-bottom: 2px solid #FF5252; padding-bottom: 6px; margin-top: 35px;\">PART II: Wave Optics</h2>\n<h2 style=\"color: #FF5252; margin-top: 25px;\">6. Wavefronts &amp; Huygens' Principle</h2>\n<h3 style=\"color: #FF5252; margin-top: 20px;\">(i) Concept &amp; Types of Wavefronts</h3>\n<p>In wave theory, a <b>wavefront</b> is defined as the continuous surface or locus connecting all points in the medium which oscillate with the exact same phase. A light ray is always perpendicular (normal) to the wavefront at every point and indicates the direction of energy propagation.</p>\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 82, 82, 0.4); border-radius: 10px; padding: 14px 16px; margin: 18px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 440px;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Diagram 5: Wavefronts, Huygens' Principle &amp; Wave Reflection/Refraction\" style=\"max-width: 100%; height: auto; display: block; border-radius: 6px; object-fit: contain;\" />\n    </div>\n    <p style=\"color: #94A3B8; font-size: 13.5px; line-height: 1.5; margin: 10px 0 0 0; text-align: center !important;\"><b>Fig 6.5:</b> Wave Optics &amp; Huygens' Principle &ndash; Propagation of Spherical, Cylindrical, and Plane Wavefronts through secondary wavelets, and wavefront geometry proving Laws of Reflection and Refraction (with change in velocity).</p>\n  </div>\n<h3 style=\"color: #FF5252; margin-top: 25px;\">(ii) Huygens' Wave Theory Postulates</h3>\n<p>In 1678, Christian Huygens proposed the wave nature of light governed by two key construction postulates:</p>\n  <ul>\n    <li>1. <b>Secondary Wavelets:</b> Every single point on a primary wavefront behaves as an independent new point source of secondary disturbance, emitting secondary spherical wavelets traveling in all forward directions with the speed of light in that medium.</li>\n    <li>2. <b>Forward Envelope:</b> The forward envelope (tangential surface) touching all these secondary spherical wavelets at a later time t gives the new position and shape of the secondary wavefront.</li>\n  </ul>\n<h2 style=\"color: #FF5252; margin-top: 35px;\">7. Proof of Laws of Reflection &amp; Refraction Using Huygens' Principle</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 82, 82, 0.5); border-radius: 8px; padding: 16px 20px; margin: 18px 0;\">\n    <div style=\"color: #FF5252; font-size: 16.5px; font-weight: bold; margin-bottom: 10px; border-bottom: 1px solid rgba(255, 82, 82, 0.3); padding-bottom: 6px;\">📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Proof of Law of Reflection (∠i = ∠r) Using Plane Wavefronts</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.75;\">\n    <b>Step 1 (Incident Wavefront Geometry):</b> Consider a plane wavefront AB incident obliquely at angle i on a plane reflecting surface XY. Ray from A touches surface at A at time t = 0. Ray from B reaches surface at C at time t = &tau; traveling distance BC = v &tau;.<br>\n    <b>Step 2 (Secondary Wavelet Construction):</b> According to Huygens' principle, point A becomes a source of secondary wavelets. In time &tau;, secondary wavelet from A expands into a hemisphere of radius AD = v &tau; in the same medium.<br>\n    The tangent CD drawn from C to this wavelet hemisphere forms the reflected plane wavefront CD, making angle r with reflecting surface XY.<br>\n    <b>Step 3 (Congruence of Triangles &Delta;ABC and &Delta;ADC):</b><br>\n    • In &Delta;ABC, &angle;B = 90&deg; (wavefront &perp; ray) &nbsp;&bull;&nbsp; In &Delta;ADC, &angle;D = 90&deg;.<br>\n    • Hypotenuse AC is common.<br>\n    • Side BC = AD = v &tau;.<br>\n    Therefore, right-angled triangles &Delta;ABC and &Delta;ADC are strictly congruent: <b>&Delta;ABC &cong; &Delta;ADC (RHS Congruence)</b>.<br>\n    <b>Step 4 (Conclusion):</b> Corresponding angles must be equal: <span style=\"color: #76FF03; font-family: monospace; font-size: 16.5px;\"><b>&angle;BAC = &angle;DCA &nbsp;&rArr;&nbsp; &angle;i = &angle;r</b></span>.<br>\n    Since incident ray, normal, and reflected ray all lie in the plane of the paper perpendicular to the wavefronts, both laws of reflection are completely proven!\n  </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.2px solid rgba(255, 82, 82, 0.5); border-radius: 8px; padding: 16px 20px; margin: 18px 0;\">\n    <div style=\"color: #FF5252; font-size: 16.5px; font-weight: bold; margin-bottom: 10px; border-bottom: 1px solid rgba(255, 82, 82, 0.3); padding-bottom: 6px;\">📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Proof of Snell's Law of Refraction (sin i / sin r = μ) Using Huygens' Principle</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.75;\">\n    <b>Step 1 (Wavefront at Interface):</b> Consider a plane wavefront AB incident at angle i on a plane refracting interface XY separating Medium 1 (speed v<sub>1</sub>) and Medium 2 (speed v<sub>2</sub>). At t = 0, point A strikes interface. In time &tau;, ray from B reaches C in medium 1: BC = v<sub>1</sub> &tau;.<br>\n    <b>Step 2 (Refracted Secondary Wavelet):</b> In the same time &tau;, secondary wavelet originating from A propagates into medium 2 with speed v<sub>2</sub>, spreading to radius AD = v<sub>2</sub> &tau;.<br>\n    The tangent CD drawn from C to the wavelet in medium 2 forms the refracted plane wavefront CD, making angle r with interface XY.<br>\n    <b>Step 3 (Trigonometric Ratios):</b><br>\n    From right-angled &Delta;ABC: <span style=\"color: #00E5FF;\"><b>sin i = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">BC</span><span style=\"padding: 0 2px; display: inline-block;\">AC</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>1</sub> &tau;</span><span style=\"padding: 0 2px; display: inline-block;\">AC</span></span></b></span>.<br>\n    From right-angled &Delta;ADC: <span style=\"color: #00E5FF;\"><b>sin r = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">AD</span><span style=\"padding: 0 2px; display: inline-block;\">AC</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>2</sub> &tau;</span><span style=\"padding: 0 2px; display: inline-block;\">AC</span></span></b></span>.<br>\n    <b>Step 4 (Dividing sin i by sin r):</b><br>\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">sin i</span><span style=\"padding: 0 2px; display: inline-block;\">sin r</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>1</sub> &tau; / AC</span><span style=\"padding: 0 2px; display: inline-block;\">v<sub>2</sub> &tau; / AC</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">v<sub>2</sub></span></span> = <sup>1</sup>&mu;<sub>2</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span></span></b></span>.<br>\n    This strictly proves Snell's Law of Refraction! Also, since &nu; is constant: <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">v<sub>2</sub></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&lambda;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">&lambda;<sub>2</sub></span></span>.\n  </div>\n  </div>\n<h2 style=\"color: #FF5252; margin-top: 35px;\">8. Interference of Light &amp; Young's Double Slit Experiment (YDSE)</h2>\n<h3 style=\"color: #FF5252; margin-top: 20px;\">(i) Superposition Principle &amp; Conditions for Interference</h3>\n<p><b>Interference of Light</b> is the phenomenon of non-uniform redistribution of light energy in space due to the superposition of two or more coherent light waves.</p>\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 82, 82, 0.4); border-radius: 10px; padding: 14px 16px; margin: 18px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 440px;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Diagram 6: Young's Double Slit Experiment (YDSE) &amp; Interference Pattern\" style=\"max-width: 100%; height: auto; display: block; border-radius: 6px; object-fit: contain;\" />\n    </div>\n    <p style=\"color: #94A3B8; font-size: 13.5px; line-height: 1.5; margin: 10px 0 0 0; text-align: center !important;\"><b>Fig 6.6:</b> Young's Double Slit Experiment &ndash; Monochromatic light illuminating two coherent pinhole slits (S<sub>1</sub>, S<sub>2</sub>) producing sustained alternating Bright and Dark fringes of uniform Fringe Width: &beta; = &lambda;D / d.</p>\n  </div>\n<h3 style=\"color: #FF5252; margin-top: 25px;\">(ii) Expression for Fringe Width &amp; Fringe Positions</h3>\n<div style=\"background: rgba(0,0,0,0.3); border-left: 4px solid #76FF03; padding: 12px 16px; border-radius: 6px; margin: 14px 0;\">\n    <p style=\"margin: 0; color: #FFFFFF; font-size: 15px;\"><b>Path Difference at point P on screen at distance y from central axis:</b></p>\n    <span style=\"color: #00E5FF; font-family: monospace; font-size: 16px;\"><b>&Delta;x = S<sub>2</sub>P - S<sub>1</sub>P = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">y d</span><span style=\"padding: 0 2px; display: inline-block;\">D</span></span></b></span>\n    <p style=\"margin: 8px 0 0 0; color: #FFFFFF; font-size: 15px;\"><b>Position of n<sup>th</sup> Bright Fringe:</b> y<sub>n</sub> = n <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&lambda; D</span><span style=\"padding: 0 2px; display: inline-block;\">d</span></span> &nbsp;&nbsp; (n = 0, 1, 2, ...)</p>\n    <p style=\"margin: 4px 0 0 0; color: #FFFFFF; font-size: 15px;\"><b>Position of n<sup>th</sup> Dark Fringe:</b> y'<sub>n</sub> = (2n - 1) <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&lambda; D</span><span style=\"padding: 0 2px; display: inline-block;\">2 d</span></span> &nbsp;&nbsp; (n = 1, 2, ...)</p>\n  </div>\n  <div style=\"background: rgba(255, 82, 82, 0.1); border: 1.5px solid #FF5252; border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"color: #FF5252; font-size: 17px; font-weight: bold; margin-bottom: 6px;\">📐 Master Expression for Fringe Width (&beta;):</div>\n    <div style=\"color: #76FF03; font-family: monospace; font-size: 18px; font-weight: bold;\">&beta; = y<sub>n+1</sub> - y<sub>n</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&lambda; D</span><span style=\"padding: 0 2px; display: inline-block;\">d</span></span></div>\n    <p style=\"color: #E2E8F0; font-size: 14.5px; margin: 8px 0 0 0; line-height: 1.6;\">All bright and dark fringes in Young's interference pattern have <b>identical, uniform width &beta;</b>!</p>\n  </div>\n<h2 style=\"color: #FF5252; margin-top: 35px;\">9. Diffraction of Light &amp; Single Slit Diffraction</h2>\n<h3 style=\"color: #FF5252; margin-top: 20px;\">(i) Phenomenon of Diffraction &amp; Single Slit Fraunhofer Diffraction</h3>\n<p><b>Diffraction</b> is the bending of light waves around sharp edges or corners of an obstacle/aperture and spreading into the region of geometrical shadow. Diffraction is prominent only when the size of the obstacle/aperture (a) is comparable to the wavelength of light (&lambda;): <b>a &approx; &lambda;</b>.</p>\n  <div style=\"background: rgba(15, 23, 42, 0.9); border: 1.5px solid rgba(255, 82, 82, 0.4); border-radius: 10px; padding: 14px 16px; margin: 18px 0; box-shadow: 0 4px 20px rgba(0,0,0,0.35); text-align: center;\">\n    <div style=\"display: flex; justify-content: center; align-items: center; background: #FFFDF8; border-radius: 8px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); margin: 0 auto; max-width: 440px;\">\n      <img src=\"data:image/jpeg;base64,\" alt=\"Diagram 7: Single Slit Fraunhofer Diffraction &amp; Width of Central Maxima\" style=\"max-width: 100%; height: auto; display: block; border-radius: 6px; object-fit: contain;\" />\n    </div>\n    <p style=\"color: #94A3B8; font-size: 13.5px; line-height: 1.5; margin: 10px 0 0 0; text-align: center !important;\"><b>Fig 6.7:</b> Single Slit Fraunhofer Diffraction &ndash; Spreading of light through narrow slit width 'a' forming broad, intense Central Maximum (linear width 2x = 2&lambda;D/a) and fading secondary diffraction maxima/minima.</p>\n  </div>\n<h3 style=\"color: #FF5252; margin-top: 25px;\">(ii) Width of Central Maximum &amp; Intensity Distribution</h3>\n<div style=\"background: rgba(255, 82, 82, 0.1); border: 1.5px solid #FF5252; border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <div style=\"color: #FF5252; font-size: 17px; font-weight: bold; margin-bottom: 6px;\">📐 Width of Central Maximum:</div>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.8;\">\n      • <b>Angular Width of Central Maximum:</b> Spread between first minima on either side (&plusmn;&theta;<sub>1</sub>):<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b>2 &theta; = 2 (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&lambda;</span><span style=\"padding: 0 2px; display: inline-block;\">a</span></span>) = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 &lambda;</span><span style=\"padding: 0 2px; display: inline-block;\">a</span></span></b></span> [Radians]<br>\n      • <b>Linear Width of Central Maximum (2x):</b> On screen at distance D:<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b>2x = 2 (D &theta;) = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 &lambda; D</span><span style=\"padding: 0 2px; display: inline-block;\">a</span></span> = 2 &beta;</b></span> [Meters]<br>\n      <i>Crucial Observation:</i> The central maximum in diffraction is <b>twice as wide (2&beta;)</b> as any secondary fringe and contains over 85% of total light energy!\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 16px; margin: 16px 0;\">\n    <b style=\"color: #FF5252; font-size: 15.5px; display: block; margin-bottom: 10px;\">Comparison Matrix: Interference vs Diffraction of Light</b>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(270px, 1fr)); gap: 10px; font-size: 14px;\">\n      <div style=\"background: rgba(0,0,0,0.3); padding: 10px 12px; border-left: 3.5px solid #38BDF8; border-radius: 6px;\">\n        <b style=\"color: #38BDF8;\">Interference (YDSE):</b>\n        <ul style=\"margin: 6px 0 0 16px; padding: 0; line-height: 1.6; color: #FFFFFF;\">\n          <li>Result of superposition of waves from <b>two separate coherent wavefronts</b>.</li>\n          <li>All bright fringes have <b>identical, uniform intensity (I<sub>0</sub>)</b>.</li>\n          <li>All fringes have <b>equal width (&beta; = &lambda;D/d)</b>.</li>\n          <li>Minima are <b>perfectly pitch dark (I<sub>min</sub> = 0)</b>.</li>\n        </ul>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.3); padding: 10px 12px; border-left: 3.5px solid #76FF03; border-radius: 6px;\">\n        <b style=\"color: #76FF03;\">Diffraction (Single Slit):</b>\n        <ul style=\"margin: 6px 0 0 16px; padding: 0; line-height: 1.6; color: #FFFFFF;\">\n          <li>Result of superposition of secondary wavelets from <b>different parts of same wavefront</b>.</li>\n          <li>Central maximum is brilliantly intense; secondary maxima <b>intensity drops rapidly (1 : 1/22 : 1/61)</b>.</li>\n          <li>Central maximum is <b>twice as wide (2&lambda;D/a)</b> as secondary fringes.</li>\n          <li>Minima are <b>not completely black</b>.</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n  <div style=\"background: rgba(255, 82, 82, 0.08); border: 1.5px solid #FF5252; border-radius: 12px; padding: 20px; margin-top: 35px;\">\n    <h3 style=\"color: #FF5252; margin-top: 0; font-size: 18px; font-weight: bold; text-align: center;\">⚡ Master Revision Formula Cheat Sheet &bull; Unit VI: Optics</h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px; margin-top: 14px; font-size: 14.5px;\">\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Mirror Formula:</b> 1/f = 1/v + 1/u &nbsp;|&nbsp; m = -v/u</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Snell's Law:</b> &mu;<sub>1</sub> sin i = &mu;<sub>2</sub> sin r &nbsp;|&nbsp; sin i<sub>c</sub> = 1/&mu;</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Curved Surface:</b> &mu;<sub>2</sub>/v - &mu;<sub>1</sub>/u = (&mu;<sub>2</sub> - &mu;<sub>1</sub>)/R</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Lens Maker's:</b> 1/f = (&mu; - 1)(1/R<sub>1</sub> - 1/R<sub>2</sub>)</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Thin Lens:</b> 1/f = 1/v - 1/u &nbsp;|&nbsp; m = v/u</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Lens Power:</b> P = 1/f(m) &nbsp;|&nbsp; P<sub>eq</sub> = P<sub>1</sub> + P<sub>2</sub></div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Prism Formula:</b> &mu; = sin[(A + D<sub>m</sub>)/2] / sin(A/2)</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Thin Prism Deviation:</b> D = (&mu; - 1) A</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Compound Microscope:</b> m = -(L/f<sub>o</sub>)(D/f<sub>e</sub>) [Normal]</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Telescope:</b> m = -f<sub>o</sub>/f<sub>e</sub> &nbsp;|&nbsp; L = f<sub>o</sub> + f<sub>e</sub></div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>YDSE Fringe Width:</b> &beta; = &lambda; D / d</div>\n      <div style=\"background: rgba(15,23,42,0.8); padding: 10px 14px; border-radius: 6px;\"><b>Diffraction Central Width:</b> 2x = 2 &lambda; D / a &nbsp;|&nbsp; 2&theta; = 2&lambda;/a</div>\n    </div>\n  </div>\n</div>";

export const c12Phy6HtmlSolutions = "\n<style>\n  p, li, div:not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n  \n  <div style=\"background: rgba(255, 82, 82, 0.08); border: 1.5px solid #FF5252; border-radius: 10px; padding: 14px 18px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #FF5252; margin: 0 0 4px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">🎯 Complete 100 Board Solutions &bull; Unit VI: Optics</h2>\n    <p class=\"text-center\" style=\"color: #FFAB91; margin: 0; font-size: 14px; text-align: center !important;\">Section A (Q1–Q40: 1 Mark VSA) &bull; Section B (Q41–Q80: 2 &amp; 3 Marks SA) &bull; Section C (Q81–Q100: 5 Marks LA)</p>\n  </div>\n<h2 style=\"color: #FF5252; border-bottom: 2px solid #FF5252; padding-bottom: 6px; margin-top: 25px;\">SECTION A: Very Short Answer (VSA) Questions (1 Mark Each &bull; Q1 to Q40)</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q1: State the two fundamental laws of reflection.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      1. The incident ray, the reflected ray, and the normal to the reflecting surface at the point of incidence all lie in the same plane.<br>2. The angle of incidence equals the angle of reflection (&angle;i = &angle;r).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q2: What is the focal length of a plane mirror?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The focal length of a plane mirror is <b>infinity (f = &infin;)</b>, and its optical power is zero (P = 0).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q3: State the relation between focal length f and radius of curvature R of a spherical mirror.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      For spherical mirrors of small aperture, focal length is exactly half of the radius of curvature: <b>f = R/2</b> (or R = 2f).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q4: Why is a convex mirror preferred as a driver's rear-view mirror in vehicles?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      A convex mirror always forms an <b>erect, diminished virtual image</b> and provides a much <b>wider field of view</b> compared to a plane or concave mirror.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q5: Write the mirror formula and define the terms involved.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The mirror formula is: <b>1/f = 1/v + 1/u</b>, where u is object distance from pole, v is image distance from pole, and f is focal length.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q6: What is the sign of magnification for (i) a real inverted image, and (ii) a virtual erect image in spherical mirrors?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      (i) For real and inverted image: <b>m &lt; 0 (negative)</b>.<br>(ii) For virtual and erect image: <b>m &gt; 0 (positive)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q7: Define absolute refractive index of a medium.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The absolute refractive index (&mu; or n) of a medium is the ratio of speed of light in vacuum (c) to the speed of light in that medium (v): <b>&mu; = c/v</b>. It is dimensionless.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q8: Does the frequency of light change when it travels from air into water?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <b>No.</b> Frequency (&nu;) is a characteristic of the light source and remains strictly constant during refraction. Only velocity and wavelength change.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q9: State Snell's law of refraction.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Snell's law states that the ratio of sine of angle of incidence to sine of angle of refraction is a constant equal to relative refractive index of second medium: <b>sin i / sin r = <sup>1</sup>&mu;<sub>2</sub> = &mu;<sub>2</sub>/&mu;<sub>1</sub></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q10: Define critical angle for total internal reflection.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Critical angle (i<sub>c</sub>) is the angle of incidence in the optically denser medium for which the corresponding angle of refraction in the rarer medium is <b>90&deg;</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q11: State the two necessary conditions for total internal reflection to occur.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      1. Light must travel from an optically <b>denser medium to a rarer medium</b>.<br>2. The angle of incidence in denser medium must be <b>greater than the critical angle (i &gt; i<sub>c</sub>)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q12: Write the mathematical relation between critical angle i_c and refractive index μ of a medium relative to air.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The relation is: <b>sin i<sub>c</sub> = 1/&mu; &nbsp;&hArr;&nbsp; &mu; = 1 / sin i<sub>c</sub></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q13: What is an optical fiber and what physical principle does it work on?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      An optical fiber is an extremely thin, flexible strand of high-quality glass/quartz silica that transmits light signals along its length via <b>repeated Total Internal Reflection (TIR)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q14: Why does a diamond sparkle with intense brilliance?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Diamond has a very high refractive index (&mu; &approx; 2.42) and small critical angle (i<sub>c</sub> &approx; 24.4&deg;). Multiple internal facets cause entering light to undergo repeated TIR before emerging.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q15: What is mirage and in which climate is it observed?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Mirage is an optical illusion observed in hot deserts/roads where inverted virtual images of distant objects appear due to total internal reflection in vertically stratified air layers of varying refractive index.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q16: Write the master formula for refraction at a single spherical curved surface.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The formula is: <b>&mu;<sub>2</sub>/v - &mu;<sub>1</sub>/u = (&mu;<sub>2</sub> - &mu;<sub>1</sub>)/R</b>, where &mu;<sub>1</sub> is rarer medium, &mu;<sub>2</sub> is denser medium, and R is radius of curvature.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q17: State the Lens Maker's Formula.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Lens Maker's Formula is: <b>1/f = (&mu; - 1) [ 1/R<sub>1</sub> - 1/R<sub>2</sub> ]</b>, where &mu; is relative refractive index of lens material, and R<sub>1</sub>, R<sub>2</sub> are radii of curvature.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q18: Define Power of a lens and state its SI unit.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Power of a lens is its ability to converge or diverge light rays, defined as reciprocal of focal length in meters: <b>P = 1/f(m)</b>. Its SI unit is <b>Dioptre (D = m<sup>-1</sup>)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q19: What is the equivalent power when two thin lenses of powers P_1 and P_2 are placed in contact?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The total equivalent power is the algebraic sum: <b>P = P<sub>1</sub> + P<sub>2</sub></b> (Equivalent focal length: 1/F = 1/f<sub>1</sub> + 1/f<sub>2</sub>).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q20: A convex lens is dipped in a liquid of refractive index equal to that of the lens material. What is its focal length in the liquid?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      When &mu;<sub>lens</sub> = &mu;<sub>liquid</sub>, (&mu; - 1) = 0 &rArr; 1/f = 0 &rArr; <b>f = &infin; (infinity)</b>. The lens behaves as a plain glass sheet and becomes completely invisible!\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q21: State the relation between angle of prism A, angle of deviation D, angle of incidence i, and angle of emergence e.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The fundamental relation is: <b>A + D = i + e &nbsp;&hArr;&nbsp; D = i + e - A</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q22: What is the condition for minimum deviation D_m in a triangular prism?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      At minimum deviation (D = D<sub>m</sub>), the light ray passes symmetrically through the prism such that: <b>i = e</b> and <b>r<sub>1</sub> = r<sub>2</sub> = r = A/2</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q23: Write the expression for deviation produced by a thin prism of small angle A.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      For a thin prism (A &le; 10&deg;), deviation is: <b>D = (&mu; - 1) A</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q24: What is the magnifying power of a simple microscope when the final image is formed at near point D = 25 cm?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The magnifying power is: <b>m = 1 + D/f</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q25: What is the magnifying power of a simple microscope in normal adjustment (image at infinity)?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The magnifying power in normal adjustment is: <b>m = D/f</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q26: Why is the focal length and aperture of the objective lens of a compound microscope kept small?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      A small focal length (f<sub>o</sub>) produces high angular magnification (m &prop; 1/f<sub>o</sub>), and a small aperture minimizes spherical aberration.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q27: Why is the objective of an astronomical telescope made with a large focal length and large aperture?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      A large aperture gathers more light from distant dim stars (high brightness &amp; resolution), while large focal length (f<sub>o</sub>) yields large magnification (m = -f<sub>o</sub>/f<sub>e</sub>).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q28: Write the formula for magnifying power of an astronomical telescope in normal adjustment.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The magnifying power is: <b>m = - f<sub>o</sub> / f<sub>e</sub></b>, and tube length is <b>L = f<sub>o</sub> + f<sub>e</sub></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q29: Name two major advantages of reflecting telescopes over refracting telescopes.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      1. <b>No Chromatic Aberration:</b> Mirrors reflect all colors equally.<br>2. <b>No Spherical Aberration:</b> Achieved using paraboloidal primary mirrors.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q30: Define a wavefront in wave optics.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      A wavefront is the continuous locus/surface connecting all particles of a medium vibrating in the exact same phase of oscillation.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q31: What is the shape of the wavefront emerging from (i) a point source, and (ii) a distant star?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      (i) Point source at finite distance: <b>Spherical Wavefront</b>.<br>(ii) Distant star at infinity: <b>Plane Wavefront</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q32: State Huygens' principle of secondary wavelets.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Every point on a primary wavefront acts as a source of secondary spherical wavelets spreading in all forward directions with the speed of light. The envelope tangential to these wavelets gives the new wavefront.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q33: Does the wavelength of light increase or decrease when traveling from air into glass?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Wavelength <b>decreases</b>: &lambda;<sub>glass</sub> = &lambda;<sub>air</sub> / &mu; (since &mu; &gt; 1, speed v decreases while frequency remains constant).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q34: Define coherent sources of light.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Two sources of light are said to be coherent if they emit light waves of identical frequency, same wavelength, and maintain a <b>constant or zero phase difference (&Delta;&phi; = const)</b> over time.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q35: Why can two independent light bulbs never act as coherent sources?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Because light emission from atoms occurs via random, uncorrelated quantum jumps of duration ~10<sup>-9</sup> s, causing the relative phase difference to fluctuate millions of times per second.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q36: State the path difference condition for constructive interference in YDSE.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      For constructive interference (bright fringe): Path difference <b>&Delta;x = n &lambda;</b>, where n = 0, 1, 2, 3...\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q37: State the path difference condition for destructive interference in YDSE.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      For destructive interference (dark fringe): Path difference <b>&Delta;x = (2n - 1) &lambda;/2</b>, where n = 1, 2, 3...\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q38: Write the expression for fringe width β in Young's Double Slit Experiment.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Fringe width is given by: <b>&beta; = &lambda; D / d</b>, where &lambda; is wavelength, D is slit-to-screen distance, and d is separation between slits.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q39: Define diffraction of light.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Diffraction is the bending of light waves around sharp corners or edges of an obstacle or aperture into the geometrical shadow region.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q40: Write the expression for the angular width of central maximum in single slit Fraunhofer diffraction.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The angular width of central maximum is: <b>2&theta; = 2 &lambda; / a</b> (radians), where a is the width of the slit.\n    </div>\n  </div>\n<h2 style=\"color: #FF5252; border-bottom: 2px solid #FF5252; padding-bottom: 6px; margin-top: 35px;\">SECTION B: Short Answer (SA) Questions (2 &amp; 3 Marks Each &bull; Q41 to Q80)</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q41: An object is placed at a distance of 15 cm in front of a concave mirror of focal length 10 cm. Find the position, magnification, and nature of the image formed.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: u = -15 cm, f = -10 cm.<br>Using Mirror Formula: 1/f = 1/v + 1/u &rArr; 1/v = 1/f - 1/u = 1/(-10) - 1/(-15) = -1/10 + 1/15 = (-3 + 2)/30 = -1/30.<br>&rArr; <b>v = -30 cm</b> (30 cm in front of mirror).<br>Magnification: <b>m = -v/u = -(-30)/(-15) = -2</b>.<br><b>Nature:</b> Real, inverted, and magnified 2 times.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q42: A convex mirror used for rear-view on an automobile has radius of curvature R = 3.00 m. If a bus is located at 5.00 m from this mirror, find the position and nature of the image.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: R = +3.00 m &rArr; f = R/2 = +1.50 m, u = -5.00 m.<br>1/v = 1/f - 1/u = 1/1.50 - 1/(-5.00) = 1/1.5 + 1/5 = 2/3 + 1/5 = (10 + 3)/15 = 13/15.<br>&rArr; <b>v = +15/13 = +1.15 m</b> (behind the mirror).<br>Magnification: <b>m = -v/u = -(1.15)/(-5.00) = +0.23</b>.<br><b>Nature:</b> Virtual, erect, and diminished (23% of original size).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q43: Explain why a pond of clear water appears shallower than its actual depth. Derive the relation between real depth and apparent depth.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Due to refraction, rays from the bottom point O bend away from normal on entering air (&mu;<sub>2</sub> = 1) from water (&mu;<sub>1</sub> = &mu;), appearing to diverge from virtual image I.<br>For small viewing angles: tan i &approx; sin i = x/d<sub>real</sub>, &nbsp; tan r &approx; sin r = x/d<sub>apparent</sub>.<br>By Snell's law: &mu; = sin r / sin i = (x/d<sub>apparent</sub>) / (x/d<sub>real</sub>) = d<sub>real</sub> / d<sub>apparent</sub>.<br>&rArr; <span style='color: #76FF03;'><b>Apparent Depth = Real Depth / &mu;</b></span> &nbsp;&bull;&nbsp; Normal shift: &Delta;y = d(1 - 1/&mu;).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q44: The refractive index of glass is 1.5. Calculate the speed of light in glass and the critical angle for glass-air interface.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      (i) Speed of light in glass: <b>v = c/&mu; = (3 &times; 10<sup>8</sup> m/s) / 1.5 = 2.0 &times; 10<sup>8</sup> m/s</b>.<br>(ii) Critical angle: sin i<sub>c</sub> = 1/&mu; = 1/1.5 = 2/3 = 0.6667.<br>&rArr; <b>i<sub>c</sub> = sin<sup>-1</sup>(0.6667) &approx; 41.8&deg;</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q45: Explain the construction and working of an optical fiber with a neat labeled principle.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <b>Construction:</b> Consists of an inner glass core of high refractive index &mu;<sub>1</sub> (~1.68) surrounded by an outer cladding of lower refractive index &mu;<sub>2</sub> (~1.44), encased in a protective polymer jacket.<br><b>Working:</b> Light enters the core at an angle &theta; &lt; &theta;<sub>a</sub> (acceptance angle). At the core-cladding boundary, angle of incidence i exceeds critical angle i<sub>c</sub>. Light undergoes repeated Total Internal Reflection (TIR) with nearly 100% efficiency, propagating losslessly through curved bends.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q46: A point object is placed at a distance of 20 cm in front of a convex spherical surface of radius of curvature 20 cm. If the refractive index of the medium changes from 1.0 (air) to 1.5 (glass), find the position of the image.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: u = -20 cm, R = +20 cm, &mu;<sub>1</sub> = 1.0, &mu;<sub>2</sub> = 1.5.<br>Formula: &mu;<sub>2</sub>/v - &mu;<sub>1</sub>/u = (&mu;<sub>2</sub> - &mu;<sub>1</sub>)/R.<br>1.5/v - 1.0/(-20) = (1.5 - 1.0)/20 &rArr; 1.5/v + 1/20 = 0.5/20 = 1/40.<br>1.5/v = 1/40 - 1/20 = -1/40 &rArr; v = 1.5 &times; (-40) = <b>-60 cm</b>.<br>Image is virtual and formed 60 cm in front of the convex surface on the same side as the object.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q47: A double convex lens of glass (&mu; = 1.5) has radii of curvature 10 cm and 15 cm. Calculate its focal length in air.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: &mu; = 1.5, R<sub>1</sub> = +10 cm, R<sub>2</sub> = -15 cm.<br>Using Lens Maker's Formula: 1/f = (&mu; - 1) [1/R<sub>1</sub> - 1/R<sub>2</sub>] = (1.5 - 1) [1/10 - (-1/15)]<br>= 0.5 [1/10 + 1/15] = 0.5 [(3 + 2)/30] = 0.5 &times; (5/30) = 0.5 &times; 1/6 = 1/12.<br>&rArr; <b>f = +12 cm</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q48: A convex lens of focal length 20 cm in air is immersed in water (&mu; = 4/3). If refractive index of lens glass is 1.5, calculate its new focal length in water.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      In air: 1/f<sub>a</sub> = (&mu;<sub>g</sub> - 1)(1/R<sub>1</sub> - 1/R<sub>2</sub>) = (1.5 - 1) K = 0.5 K &rArr; K = 2/f<sub>a</sub>.<br>In water: 1/f<sub>w</sub> = (<sup>w</sup>&mu;<sub>g</sub> - 1) K = (1.5 / (4/3) - 1) K = (9/8 - 1) K = (1/8) K = (1/8)(2/f<sub>a</sub>) = 1 / (4 f<sub>a</sub>).<br>&rArr; <b>f<sub>w</sub> = 4 f<sub>a</sub> = 4 &times; 20 cm = +80 cm</b>.<br>The focal length increases 4 times in water.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q49: Two thin lenses of focal lengths +20 cm and -10 cm are placed in coaxial contact. Find the power and focal length of the combination. Is the combination converging or diverging?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: f<sub>1</sub> = +20 cm = +0.20 m &rArr; P<sub>1</sub> = 1/0.20 = +5 D.<br>f<sub>2</sub> = -10 cm = -0.10 m &rArr; P<sub>2</sub> = 1/(-0.10) = -10 D.<br>(i) Equivalent Power: <b>P = P<sub>1</sub> + P<sub>2</sub> = +5 D - 10 D = -5 D</b>.<br>(ii) Equivalent Focal length: <b>F = 1/P = 1/(-5) m = -0.20 m = -20 cm</b>.<br>(iii) Nature: Since F &lt; 0 and P &lt; 0, the combination behaves as a <b>diverging (concave) lens</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q50: Calculate the angle of minimum deviation for an equilateral glass prism of refractive index &mu; = &radic;3.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      For an equilateral prism: A = 60&deg; &rArr; A/2 = 30&deg;.<br>Prism formula: &mu; = sin[(A + D<sub>m</sub>)/2] / sin(A/2) &rArr; &radic;3 = sin[(60&deg; + D<sub>m</sub>)/2] / sin(30&deg;).<br>sin[(60&deg; + D<sub>m</sub>)/2] = &radic;3 &times; 0.5 = &radic;3 / 2 = sin(60&deg;).<br>(60&deg; + D<sub>m</sub>)/2 = 60&deg; &rArr; 60&deg; + D<sub>m</sub> = 120&deg; &rArr; <b>D<sub>m</sub> = 60&deg;</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q51: A ray of light passes through an equilateral prism such that angle of incidence equals angle of emergence, and each is 3/4 of the angle of the prism. Calculate the angle of deviation.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: A = 60&deg;, i = e = (3/4) A = (3/4) &times; 60&deg; = 45&deg;.<br>Using A + D = i + e &rArr; 60&deg; + D = 45&deg; + 45&deg; = 90&deg;.<br>&rArr; <b>D = 90&deg; - 60&deg; = 30&deg;</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q52: A compound microscope has an objective of focal length 1.0 cm and eyepiece of focal length 2.5 cm. An object is placed 1.2 cm from objective. Find magnification if final image is at near point D = 25 cm.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Objective: u<sub>o</sub> = -1.2 cm, f<sub>o</sub> = +1.0 cm.<br>1/v<sub>o</sub> = 1/f<sub>o</sub> + 1/u<sub>o</sub> = 1/1.0 - 1/1.2 = 1 - 5/6 = 1/6 &rArr; v<sub>o</sub> = +6.0 cm.<br>Objective magnification: m<sub>o</sub> = -v<sub>o</sub>/u<sub>o</sub> = -6.0 / (-1.2) = 5.<br>Eyepiece magnification: m<sub>e</sub> = 1 + D/f<sub>e</sub> = 1 + 25/2.5 = 1 + 10 = 11.<br>Total Magnification: <b>m = m<sub>o</sub> &times; m<sub>e</sub> = 5 &times; 11 = 55</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q53: An astronomical telescope has an objective of focal length 140 cm and eyepiece of focal length 5.0 cm. What is the magnifying power and length of the telescope in normal adjustment?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: f<sub>o</sub> = 140 cm, f<sub>e</sub> = 5.0 cm.<br>(i) Magnifying power: <b>m = - f<sub>o</sub> / f<sub>e</sub> = - 140 / 5.0 = -28</b> (inverted image).<br>(ii) Length of telescope tube: <b>L = f<sub>o</sub> + f<sub>e</sub> = 140 cm + 5 cm = 145 cm</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q54: State the differences between the objective of a telescope and the objective of a microscope.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      1. <b>Telescope Objective:</b> Has large focal length (f<sub>o</sub>) and very large aperture to collect ample light from distant faint stars.<br>2. <b>Microscope Objective:</b> Has very small focal length (f<sub>o</sub>) and small aperture to yield high linear magnification of tiny nearby objects.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q55: Explain why secondary wavelets have zero amplitude in the backward direction.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      According to Fresnel and Voigt, the amplitude of a secondary wavelet is proportional to the <b>obliquity factor: (1 + cos &theta;)/2</b>, where &theta; is angle with forward normal. For the backward direction, &theta; = 180&deg; &rArr; cos(180&deg;) = -1 &rArr; (1 - 1)/2 = <b>0</b>. Hence, no backward wavefront propagates.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q56: In Young's double slit experiment, the slits are separated by 0.28 mm and screen is placed 1.4 m away. If the distance between central bright fringe and 4th bright fringe is 1.2 cm, find the wavelength of light.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: d = 0.28 mm = 0.28 &times; 10<sup>-3</sup> m, D = 1.4 m, y<sub>4</sub> = 1.2 cm = 1.2 &times; 10<sup>-2</sup> m, n = 4.<br>Formula: y<sub>n</sub> = n &lambda; D / d &rArr; &lambda; = (y<sub>4</sub> &times; d) / (4 D).<br>&lambda; = (1.2 &times; 10<sup>-2</sup> &times; 0.28 &times; 10<sup>-3</sup>) / (4 &times; 1.4) = (3.36 &times; 10<sup>-6</sup>) / 5.6 = 0.6 &times; 10<sup>-6</sup> m = <b>600 nm = 6000 &Aring;</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q57: What is the effect on the interference fringes in YDSE if (i) the monochromatic source is replaced by white light, and (ii) screen is moved away from slits?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      (i) <b>White light:</b> Central fringe is white (zero path difference for all colors). Adjacent fringes are colored with violet on inside and red on outside; further out, pattern washes out into uniform white illumination.<br>(ii) <b>Screen moved away (D increases):</b> Fringe width &beta; = &lambda;D/d increases; fringes become wider and more spread out.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q58: Two coherent sources have intensity ratio 81:1. Find the ratio of maximum to minimum intensity in their interference pattern.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: I<sub>1</sub>/I<sub>2</sub> = 81/1 &rArr; a<sub>1</sub>/a<sub>2</sub> = &radic;(81/1) = 9/1.<br>I<sub>max</sub> / I<sub>min</sub> = (a<sub>1</sub> + a<sub>2</sub>)<sup>2</sup> / (a<sub>1</sub> - a<sub>2</sub>)<sup>2</sup> = (9 + 1)<sup>2</sup> / (9 - 1)<sup>2</sup> = (10)<sup>2</sup> / (8)<sup>2</sup> = 100 / 64 = <b>25 / 16 (or 25:16)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q59: A parallel beam of light of wavelength 500 nm falls on a narrow slit and the resulting diffraction pattern is observed on a screen 1 m away. If the first minimum is 2.5 mm from the center of screen, calculate the width of the slit.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: &lambda; = 500 nm = 5 &times; 10<sup>-7</sup> m, D = 1 m, x<sub>1</sub> = 2.5 mm = 2.5 &times; 10<sup>-3</sup> m.<br>First minimum condition: x<sub>1</sub> = &lambda; D / a &rArr; a = &lambda; D / x<sub>1</sub>.<br>a = (5 &times; 10<sup>-7</sup> &times; 1) / (2.5 &times; 10<sup>-3</sup>) = 2 &times; 10<sup>-4</sup> m = <b>0.2 mm</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q60: Why is diffraction not easily observed in sound waves with tiny openings but easily observed with light only in microscopic slits?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Diffraction requires obstacle/slit size comparable to wavelength (a &approx; &lambda;). Sound waves have wavelengths &lambda; ~ 1 m (comparable to doors/windows), so sound bends easily. Visible light has tiny &lambda; ~ 5 &times; 10<sup>-7</sup> m, so light diffraction is visible only with microscopic slits/pinholes.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q61: Explain why a combination of lenses is preferred over a single lens in optical devices.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      1. Increases net angular magnification: m = m<sub>1</sub> &times; m<sub>2</sub>.<br>2. Reduces spherical and chromatic aberrations.<br>3. Increases field of view and image sharpness.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q62: What is chromatic aberration and how is it minimized?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Chromatic aberration is the failure of a lens to focus all colors of white light to the same point because refractive index varies with wavelength (&mu;<sub>violet</sub> &gt; &mu;<sub>red</sub>). It is eliminated by combining a convex lens of crown glass with a concave lens of flint glass (Achromatic Doublet) or using reflecting mirrors.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q63: Derive the condition for total internal reflection inside an equilateral prism of refractive index μ.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      For a ray entering normally at face 1 (i = 0 &rArr; r<sub>1</sub> = 0), it strikes face 2 at angle r<sub>2</sub> = A = 60&deg;.<br>For TIR at face 2: r<sub>2</sub> &gt; i<sub>c</sub> &rArr; 60&deg; &gt; sin<sup>-1</sup>(1/&mu;) &rArr; sin(60&deg;) &gt; 1/&mu; &rArr; &radic;3/2 &gt; 1/&mu; &rArr; <b>&mu; &gt; 2/&radic;3 &approx; 1.155</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q64: An illuminated object and a screen are placed 90 cm apart. Determine the focal length and nature of the lens required to produce a real image on screen magnified 2 times.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Given: |u| + v = 90 cm. Real image &rArr; m = -v/u = -2 &rArr; v = 2|u|.<br>|u| + 2|u| = 90 &rArr; 3|u| = 90 &rArr; |u| = 30 cm &rArr; u = -30 cm, v = +60 cm.<br>Lens formula: 1/f = 1/v - 1/u = 1/60 - 1/(-30) = 1/60 + 2/60 = 3/60 = 1/20.<br>&rArr; <b>f = +20 cm</b>. A <b>convex lens</b> of focal length 20 cm is required.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q65: State the main differences between primary and secondary rainbows.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      1. <b>Primary Rainbow:</b> Formed by two refractions and ONE internal reflection in raindrops; inner edge is violet, outer edge is red; brighter (subtends ~42&deg;).<br>2. <b>Secondary Rainbow:</b> Formed by two refractions and TWO internal reflections in raindrops; color order is reversed (inner red, outer violet); fainter (subtends ~53&deg;).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q66: Why does the sky appear blue during daytime and reddish at sunset?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      According to Rayleigh Scattering law: Intensity I &prop; 1/&lambda;<sup>4</sup>.<br>• <b>Blue Sky:</b> Blue light has short wavelength (&lambda; &approx; 400 nm), scattering ~10 times more than red in atmospheric molecules.<br>• <b>Red Sunset:</b> At sunrise/sunset, sunlight travels longest atmospheric path. Short blue wavelengths are scattered away, and only unscattered long red wavelengths (&lambda; &approx; 700 nm) reach our eyes.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q67: Explain why stars twinkle but planets do not.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Stars are point-sized sources located light-years away; atmospheric turbulence causes fluctuating refraction, shifting the star's apparent position and intensity. Planets are closer, acting as extended discs (collection of many point sources); fluctuations from different points average out to zero net change.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q68: A convex lens made of material with refractive index 1.5 is placed in a medium of refractive index 1.65. What change occurs in its nature and focal length?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Relative refractive index &mu; = &mu;<sub>lens</sub> / &mu;<sub>medium</sub> = 1.5 / 1.65 = 10/11 &lt; 1.<br>Since (&mu; - 1) = (10/11 - 1) = -1/11 &lt; 0, focal length f becomes <b>negative</b>.<br>The convex lens <b>reverses its behavior and acts as a Diverging (Concave) Lens</b> in the denser liquid!\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q69: State the conditions under which a lens behaves as a plane glass plate.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      A lens behaves as a plane glass plate (f = &infin;, P = 0) when it is immersed in a liquid having the <b>exact same refractive index as the lens material (&mu;<sub>medium</sub> = &mu;<sub>lens</sub>)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q70: State the relation between fringe width β and separation between slits d in YDSE. If d is halved and D is doubled, what happens to fringe width?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Formula: &beta; = &lambda; D / d.<br>New parameters: d' = d/2, D' = 2D.<br>&beta;' = &lambda; (2D) / (d/2) = 4 (&lambda; D / d) = <b>4 &beta;</b>.<br>The fringe width becomes <b>4 times larger</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q71: Can interference occur with two independent laser torches? Explain.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <b>No.</b> Even though lasers produce highly monochromatic and directional light, two independent lasers emit light from separate atomic systems with randomly drifting phase differences over time. Sustained interference requires a single laser beam split into two coherent beams.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q72: In YDSE, what is the phase difference between waves arriving at a point where path difference is (i) λ/4, and (ii) λ/2?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Relation: &Delta;&phi; = (2&pi;/&lambda;) &Delta;x.<br>(i) For &Delta;x = &lambda;/4: &Delta;&phi; = (2&pi;/&lambda;)(&lambda;/4) = <b>&pi;/2 rad (90&deg;)</b>.<br>(ii) For &Delta;x = &lambda;/2: &Delta;&phi; = (2&pi;/&lambda;)(&lambda;/2) = <b>&pi; rad (180&deg;)</b> (Destructive minimum).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q73: What is the shape of interference fringes in Young's Double Slit Experiment?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      The locus of points with constant path difference (&Delta;x = const) from two pinholes on a screen is a <b>hyperbola</b>. Near the central axis of the screen, they appear as straight, parallel, equidistant bright and dark lines.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q74: Why is the central fringe in single slit diffraction bright and broad?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      At the central point &theta; = 0, wavelets from all parts of the slit arrive in the exact same phase (zero path difference), interfering constructively with maximum amplitude (A = a<sub>0</sub>) and maximum intensity.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q75: Differentiate between Fresnel diffraction and Fraunhofer diffraction.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      1. <b>Fresnel Diffraction:</b> Source of light and screen are at <b>finite distances</b> from the diffracting obstacle; wavefronts are spherical/cylindrical; no lenses required.<br>2. <b>Fraunhofer Diffraction:</b> Source and screen are effectively at <b>infinite distances</b>; wavefronts are planar; convex lenses are used to focus plane wavefronts.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q76: How does the angular width of central maximum in single slit diffraction change if (i) slit width is doubled, (ii) wavelength of light is halved?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Angular width: 2&theta; = 2&lambda;/a.<br>(i) Slit width doubled (a' = 2a): 2&theta;' = 2&lambda;/(2a) = (2&theta;)/2 &rArr; <b>Angular width is halved</b>.<br>(ii) Wavelength halved (&lambda;' = &lambda;/2): 2&theta;' = 2(&lambda;/2)/a = (2&theta;)/2 &rArr; <b>Angular width is halved</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q77: What is the Brewster's law of polarization?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Brewster's law states that when unpolarized light is incident at polarizing angle i<sub>p</sub> on a transparent dielectric, the reflected ray is completely linearly polarized perpendicular to the plane of incidence, and: <b>&mu; = tan i<sub>p</sub></b> (reflected and refracted rays are mutually perpendicular: r + i<sub>p</sub> = 90&deg;).\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q78: Why does a diamond cut by an expert shine more than an uncut piece of glass?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      Diamond's refractive index (&mu; &approx; 2.42) is much higher than glass (&mu; &approx; 1.5), giving it a tiny critical angle i<sub>c</sub> &approx; 24.4&deg; (vs 42&deg; for glass). An expert cuts facets at angles &gt; 24.4&deg; so light entering undergoes multiple internal reflections before emerging.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q79: Can sound waves exhibit polarization? Why or why not?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <b>No.</b> Polarization is a unique property exhibited strictly by <b>transverse waves</b>. Sound waves in air are longitudinal (oscillations parallel to propagation) and cannot be polarized.\n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q80: Why is the core of an optical fiber made of higher refractive index material than cladding?</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      To satisfy the fundamental condition of Total Internal Reflection (TIR), light must travel from a <b>denser medium (&mu;<sub>core</sub> &approx; 1.68)</b> toward a <b>rarer medium (&mu;<sub>cladding</sub> &approx; 1.44)</b> so that at the interface, i &gt; i<sub>c</sub> and light is reflected back inside the core.\n    </div>\n  </div>\n<h2 style=\"color: #FF5252; border-bottom: 2px solid #FF5252; padding-bottom: 6px; margin-top: 35px;\">SECTION C: Long Answer (LA) Questions (5 Marks Each &bull; Q81 to Q100)</h2>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q81: Derive the Mirror Formula (1/f = 1/v + 1/u) for a concave mirror forming a real image, stating all sign conventions.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Geometric Setup:</b> Consider a concave mirror of small aperture with pole P, focus F, and center of curvature C (where PC = R = 2f). An object AB is placed perpendicular to principal axis beyond C.<br>\n      • Ray AP parallel to axis reflects through F.<br>\n      • Ray directed at pole P reflects symmetrically such that &angle;APB = &angle;A'PB'.<br>\n      Real inverted image A'B' is formed between C and F.<br>\n      <b>2. Similar Triangles:</b><br>\n      From similar right-angled &Delta;ABP and &Delta;A'B'P:<br>\n      <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">A'B'</span><span style=\"padding: 0 2px; display: inline-block;\">AB</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">PB'</span><span style=\"padding: 0 2px; display: inline-block;\">PB</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">-v</span><span style=\"padding: 0 2px; display: inline-block;\">-u</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v</span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span>. &nbsp;&nbsp; ...(1)<br>\n      From similar &Delta;ABC and &Delta;A'B'C:<br>\n      <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">A'B'</span><span style=\"padding: 0 2px; display: inline-block;\">AB</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">CB'</span><span style=\"padding: 0 2px; display: inline-block;\">BC</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">PC - PB'</span><span style=\"padding: 0 2px; display: inline-block;\">PB - PC</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">-R - (-v)</span><span style=\"padding: 0 2px; display: inline-block;\">-u - (-R)</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">-R + v</span><span style=\"padding: 0 2px; display: inline-block;\">-u + R</span></span>. &nbsp;&nbsp; ...(2)<br>\n      <b>3. Equating &amp; Algebraic Reduction:</b><br>\n      <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v</span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">-R + v</span><span style=\"padding: 0 2px; display: inline-block;\">-u + R</span></span> &rArr; -u v + v R = -u R + u v &rArr; (u + v) R = 2 u v.<br>\n      Substituting R = 2f:<br>\n      (u + v)(2f) = 2 u v &rArr; u f + v f = u v.<br>\n      Dividing both sides by u v f:<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">f</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span></b></span>.<br>\n      <b>Linear Magnification:</b> m = h<sub>i</sub>/h<sub>o</sub> = -v/u = f/(f - u).\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q82: Derive the master relation for refraction at a single spherical curved surface: &mu;<sub>2</sub>/v - &mu;<sub>1</sub>/u = (&mu;<sub>2</sub> - &mu;<sub>1</sub>)/R.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Ray Construction:</b> Consider a convex spherical surface separating medium 1 (&mu;<sub>1</sub>) from denser medium 2 (&mu;<sub>2</sub>). Radius of curvature is R. Point object O is placed on principal axis in medium 1. Ray OM strikes surface at M and refracts along MI, intersecting principal axis at image point I. MC is normal to surface.<br>\n      Let &alpha;, &beta;, &gamma; be angles subtended by OM, MI, and MC with principal axis. Drop MP &perp; axis.<br>\n      <b>2. Triangle Angles:</b><br>\n      In &Delta;OMC: i = &alpha; + &gamma; (exterior angle).<br>\n      In &Delta;MIC: &gamma; = r + &beta; &rArr; r = &gamma; - &beta;.<br>\n      <b>3. Small Angle Approximations (Paraxial Rays):</b><br>\n      &alpha; &approx; tan &alpha; = MP/(-u), &nbsp; &beta; &approx; tan &beta; = MP/v, &nbsp; &gamma; &approx; tan &gamma; = MP/R.<br>\n      <b>4. Applying Snell's Law for Small Angles (&mu;<sub>1</sub> i = &mu;<sub>2</sub> r):</b><br>\n      &mu;<sub>1</sub> (&alpha; + &gamma;) = &mu;<sub>2</sub> (&gamma; - &beta;) &rArr; &mu;<sub>1</sub> &alpha; + &mu;<sub>2</sub> &beta; = (&mu;<sub>2</sub> - &mu;<sub>1</sub>) &gamma;.<br>\n      Substituting angle values:<br>\n      &mu;<sub>1</sub> [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">MP</span><span style=\"padding: 0 2px; display: inline-block;\">-u</span></span> ] + &mu;<sub>2</sub> [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">MP</span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span> ] = (&mu;<sub>2</sub> - &mu;<sub>1</sub>) [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">MP</span><span style=\"padding: 0 2px; display: inline-block;\">R</span></span> ].<br>\n      Canceling MP on both sides:<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub> - &mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">R</span></span></b></span>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q83: Derive the Lens Maker's Formula 1/f = (&mu; - 1)[1/R<sub>1</sub> - 1/R<sub>2</sub>] for a thin double convex lens.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Refraction at First Surface (Radius R<sub>1</sub>):</b><br>\n      Ray from point object O at distance u in medium &mu;<sub>1</sub> refracts at surface 1 forming intermediate virtual image I' at distance v' in medium &mu;<sub>2</sub>:<br>\n      <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">v'</span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub> - &mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>1</sub></span></span>. &nbsp;&nbsp; ...(1)<br>\n      <b>2. Refraction at Second Surface (Radius R<sub>2</sub>):</b><br>\n      Intermediate image I' acts as virtual object for surface 2 (traveling from &mu;<sub>2</sub> to &mu;<sub>1</sub>), forming final real image at distance v:<br>\n      <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">v'</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub> - &mu;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>2</sub></span></span> = - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub> - &mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>2</sub></span></span>. &nbsp;&nbsp; ...(2)<br>\n      <b>3. Summing Both Equations:</b><br>\n      Adding (1) and (2):<br>\n      <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span> = (&mu;<sub>2</sub> - &mu;<sub>1</sub>) [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>1</sub></span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>2</sub></span></span> ].<br>\n      Dividing both sides by &mu;<sub>1</sub>:<br>\n      <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span> = (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span></span> - 1) [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>1</sub></span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>2</sub></span></span> ].<br>\n      <b>4. Final Formula:</b> When u = &infin;, v = f &rArr; 1/f = 1/v - 1/u:<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">f</span></span> = (&mu; - 1) [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>1</sub></span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">R<sub>2</sub></span></span> ]</b></span> (where &mu; = &mu;<sub>2</sub>/&mu;<sub>1</sub>).\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q84: Derive the Prism Formula &mu; = sin[(A + D_m)/2] / sin(A/2) for a triangular glass prism.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Geometric Construction:</b> Consider principal section ABC of a glass prism of refracting angle A. A monochromatic ray PQ is incident at angle i on face AB, refracts inside along QR at angle r<sub>1</sub>, strikes face AC at angle r<sub>2</sub>, and emerges along RS at angle e.<br>\n      In quadrilateral AQNR: &angle;A + &angle;QNR = 180&deg;.<br>\n      In &Delta;QNR: r<sub>1</sub> + r<sub>2</sub> + &angle;QNR = 180&deg;.<br>\n      Comparing gives: <span style=\"color: #00E5FF;\"><b>A = r<sub>1</sub> + r<sub>2</sub></b></span>. &nbsp;&nbsp; ...(1)<br>\n      <b>2. Angle of Deviation:</b><br>\n      Total deviation D = &delta;<sub>1</sub> + &delta;<sub>2</sub> = (i - r<sub>1</sub>) + (e - r<sub>2</sub>) = (i + e) - (r<sub>1</sub> + r<sub>2</sub>).<br>\n      Using (1): <span style=\"color: #00E5FF;\"><b>D = i + e - A &nbsp;&hArr;&nbsp; A + D = i + e</b></span>. &nbsp;&nbsp; ...(2)<br>\n      <b>3. Condition of Minimum Deviation (D = D<sub>m</sub>):</b><br>\n      At minimum deviation, ray passes symmetrically through prism parallel to base:<br>\n      i = e &nbsp;&nbsp; and &nbsp;&nbsp; r<sub>1</sub> = r<sub>2</sub> = r.<br>\n      From (1): A = r + r = 2r &rArr; <span style=\"color: #76FF03;\"><b>r = A/2</b></span>.<br>\n      From (2): A + D<sub>m</sub> = i + i = 2i &rArr; <span style=\"color: #76FF03;\"><b>i = (A + D<sub>m</sub>)/2</b></span>.<br>\n      <b>4. Applying Snell's Law &mu; = sin i / sin r:</b><br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17.5px;\"><b>&mu; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">sin [ (A + D<sub>m</sub>) / 2 ]</span><span style=\"padding: 0 2px; display: inline-block;\">sin (A / 2)</span></span></b></span>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q85: Derive the expression for the magnifying power of a Compound Microscope in (i) Normal adjustment, and (ii) Least distance of distinct vision.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Optical Ray Path:</b> An object AB is placed just beyond focal point F<sub>o</sub> of objective lens (f<sub>o</sub>), forming real inverted magnified image A'B' at distance v<sub>o</sub>. This image acts as object for eyepiece (f<sub>e</sub>), which forms final magnified virtual image A''B'' at distance D.<br>\n      <b>2. Total Magnification:</b> m = m<sub>objective</sub> &times; m<sub>eyepiece</sub> = (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>o</sub></span><span style=\"padding: 0 2px; display: inline-block;\">-u<sub>o</sub></span></span>) &times; m<sub>e</sub>.<br>\n      <b>Case (i): Final Image at Least Distance of Distinct Vision (D = 25 cm):</b><br>\n      The eyepiece functions as a simple magnifier forming image at D:<br>\n      m<sub>e</sub> = 1 + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">D</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span>.<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 16.5px;\"><b>m = - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>o</sub></span><span style=\"padding: 0 2px; display: inline-block;\">u<sub>o</sub></span></span> [ 1 + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">D</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span> ] &approx; - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>o</sub></span></span> [ 1 + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">D</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span> ]</b></span> (where L &approx; v<sub>o</sub> is tube length).<br>\n      <b>Case (ii): Normal Adjustment (Final Image at Infinity):</b><br>\n      Eyepiece has image at infinity &rArr; m<sub>e</sub> = D/f<sub>e</sub>.<br>\n      <span style=\"color: #00E5FF; font-family: monospace; font-size: 16.5px;\"><b>m = - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>o</sub></span><span style=\"padding: 0 2px; display: inline-block;\">u<sub>o</sub></span></span> (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">D</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span>) &approx; - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>o</sub></span></span> (<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">D</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span>)</b></span>.<br>\n      Tube length: <b>L = v<sub>o</sub> + f<sub>e</sub></b>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q86: Derive the formula for magnifying power of an Astronomical Refracting Telescope and state why Cassegrain reflecting telescopes are preferred.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Principle &amp; Ray Diagram:</b> Parallel rays from distant object at angle &alpha; enter objective (f<sub>o</sub>, large aperture) forming inverted real image A'B' at its focus F<sub>o</sub>. Eyepiece (f<sub>e</sub>) is adjusted so A'B' lies at its focal point F<sub>e</sub>, producing final image at infinity subtending angle &beta;.<br>\n      <b>2. Magnification Derivation:</b><br>\n      Angular Magnification: m = &beta; / &alpha; &approx; tan &beta; / tan &alpha;.<br>\n      From right &Delta;A'B'O: tan &alpha; = A'B' / f<sub>o</sub>.<br>\n      From right &Delta;A'B'E: tan &beta; = A'B' / (-f<sub>e</sub>).<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b>m = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">tan &beta;</span><span style=\"padding: 0 2px; display: inline-block;\">tan &alpha;</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">A'B' / (-f<sub>e</sub>)</span><span style=\"padding: 0 2px; display: inline-block;\">A'B' / f<sub>o</sub></span></span> = - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f<sub>o</sub></span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span></b></span>.<br>\n      Tube Length: <b>L = f<sub>o</sub> + f<sub>e</sub></b>.<br>\n      <b>3. Superiority of Cassegrain Reflecting Telescope:</b><br>\n      • Eliminates chromatic aberration completely (reflection is wavelength-independent).<br>\n      • Eliminates spherical aberration using a paraboloidal primary mirror.<br>\n      • Large concave mirror (several meters wide) can be supported over its full back surface, avoiding mechanical sagging.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q87: Using Huygens' Principle, prove the Laws of Reflection (&angle;i = &angle;r) for a plane wave incident on a plane surface.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Construction:</b> Let XY be a plane reflecting surface. A plane wavefront AB is incident obliquely at angle i. At time t = 0, edge A touches the surface. In time &tau;, point B of wavefront reaches point C on surface XY traveling distance BC = v &tau;.<br>\n      <b>2. Huygens' Secondary Wavelet:</b> Point A acts as source emitting secondary wavelets in the same medium at speed v. In time &tau;, the wavelet from A grows to radius AD = v &tau;.<br>\n      Tangent plane CD drawn from C to the wavelet hemisphere represents the reflected plane wavefront making angle r with XY.<br>\n      <b>3. Geometric Congruence Proof:</b><br>\n      In &Delta;ABC and &Delta;ADC:<br>\n      • &angle;ABC = &angle;ADC = 90&deg; (wavefront is perpendicular to rays).<br>\n      • Hypotenuse AC is common to both triangles.<br>\n      • Side BC = AD = v &tau;.<br>\n      Therefore, <b>&Delta;ABC &cong; &Delta;ADC (RHS congruence rule)</b>.<br>\n      <b>4. Conclusion:</b><br>\n      Corresponding angles are equal: <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b>&angle;BAC = &angle;DCA &rArr; &angle;i = &angle;r</b></span>.<br>\n      Since the incident wavefront, normal, and reflected wavefront are all perpendicular to the plane of the diagram, the incident ray, normal, and reflected ray all lie in the same plane.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q88: Using Huygens' Principle, prove Snell's Law of Refraction (&mu;<sub>1</sub> sin i = &mu;<sub>2</sub> sin r) for a plane wave at a plane interface.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Setup:</b> Consider plane interface XY separating Medium 1 (speed v<sub>1</sub>, index &mu;<sub>1</sub>) and Medium 2 (speed v<sub>2</sub>, index &mu;<sub>2</sub>). Plane wavefront AB is incident at angle i. At t = 0, point A touches interface. In time &tau;, ray from B reaches C in medium 1: <b>BC = v<sub>1</sub> &tau;</b>.<br>\n      <b>2. Secondary Wavelet in Medium 2:</b> Secondary wavelet from A propagates into medium 2 at speed v<sub>2</sub>. In time &tau;, it forms a spherical hemisphere of radius <b>AD = v<sub>2</sub> &tau;</b>.<br>\n      Tangent plane CD drawn from C to this hemisphere gives the refracted plane wavefront making angle r with interface XY.<br>\n      <b>3. Right Triangle Ratios:</b><br>\n      In right-angled &Delta;ABC: <span style=\"color: #00E5FF;\"><b>sin i = BC / AC = (v<sub>1</sub> &tau;) / AC</b></span>.<br>\n      In right-angled &Delta;ADC: <span style=\"color: #00E5FF;\"><b>sin r = AD / AC = (v<sub>2</sub> &tau;) / AC</b></span>.<br>\n      <b>4. Ratio of sin i to sin r:</b><br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17.5px;\"><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">sin i</span><span style=\"padding: 0 2px; display: inline-block;\">sin r</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">(v<sub>1</sub> &tau;) / AC</span><span style=\"padding: 0 2px; display: inline-block;\">(v<sub>2</sub> &tau;) / AC</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">v<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">v<sub>2</sub></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">c / &mu;<sub>1</sub></span><span style=\"padding: 0 2px; display: inline-block;\">c / &mu;<sub>2</sub></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span></span> = <sup>1</sup>&mu;<sub>2</sub></b></span>.<br>\n      This strictly proves Snell's Law: <b>&mu;<sub>1</sub> sin i = &mu;<sub>2</sub> sin r</b>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q89: Describe Young's Double Slit Experiment (YDSE) and derive the mathematical expression for fringe width &beta; = &lambda;D/d.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Principle &amp; Path Difference:</b> Monochromatic light of wavelength &lambda; from single slit illuminates two narrow parallel slits S<sub>1</sub> and S<sub>2</sub> separated by distance d. Screen is placed at distance D (D &gt;&gt; d).<br>\n      Consider a point P on screen at distance y from central axis O.<br>\n      In right &Delta;S<sub>2</sub>P M: S<sub>2</sub>P<sup>2</sup> = D<sup>2</sup> + (y + d/2)<sup>2</sup>.<br>\n      In right &Delta;S<sub>1</sub>P N: S<sub>1</sub>P<sup>2</sup> = D<sup>2</sup> + (y - d/2)<sup>2</sup>.<br>\n      Subtracting: S<sub>2</sub>P<sup>2</sup> - S<sub>1</sub>P<sup>2</sup> = [ (y + d/2)<sup>2</sup> - (y - d/2)<sup>2</sup> ] = 4 y (d/2) = 2 y d.<br>\n      (S<sub>2</sub>P - S<sub>1</sub>P)(S<sub>2</sub>P + S<sub>1</sub>P) = 2 y d.<br>\n      Since D &gt;&gt; d &gt;&gt; y, S<sub>2</sub>P + S<sub>1</sub>P &approx; 2D:<br>\n      Path Difference: <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\"><b>&Delta;x = S<sub>2</sub>P - S<sub>1</sub>P = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">y d</span><span style=\"padding: 0 2px; display: inline-block;\">D</span></span></b></span>.<br>\n      <b>2. Positions of Bright Fringes (Constructive Interference):</b><br>\n      &Delta;x = n &lambda; &rArr; y<sub>n</sub> d / D = n &lambda; &rArr; <b>y<sub>n</sub> = n <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&lambda; D</span><span style=\"padding: 0 2px; display: inline-block;\">d</span></span></b> (n = 0, 1, 2, ...).<br>\n      <b>3. Fringe Width (&beta;):</b> Separation between consecutive bright fringes:<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17.5px;\"><b>&beta; = y<sub>n+1</sub> - y<sub>n</sub> = (n + 1)<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&lambda; D</span><span style=\"padding: 0 2px; display: inline-block;\">d</span></span> - n<span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&lambda; D</span><span style=\"padding: 0 2px; display: inline-block;\">d</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&lambda; D</span><span style=\"padding: 0 2px; display: inline-block;\">d</span></span></b></span>.<br>\n      All bright and dark fringes have identical uniform width &beta;.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q90: Discuss single slit Fraunhofer diffraction. Explain the formation of central maximum and secondary minima/maxima with width calculations.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Theoretical Mechanism:</b> A monochromatic plane wavefront of wavelength &lambda; is incident on a slit AB of width a. According to Huygens' principle, all points in slit AB emit secondary wavelets in phase. A convex lens focuses wavelets diffracted at angle &theta; on a screen at distance D.<br>\n      Path difference between wavelets from top edge A and bottom edge B is: <b>&Delta;x = a sin &theta;</b>.<br>\n      <b>2. Secondary Minima (Dark Bands):</b><br>\n      When a sin &theta;<sub>n</sub> = n &lambda; (n = 1, 2, 3, ...), the slit can be divided into 2n equal halves. Every wavelet from the upper half is canceled by an opposite wavelet from the lower half with path difference &lambda;/2.<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\"><b>a sin &theta;<sub>n</sub> = n &lambda; &nbsp;&rArr;&nbsp; &theta;<sub>n</sub> &approx; n <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&lambda;</span><span style=\"padding: 0 2px; display: inline-block;\">a</span></span></b></span>.<br>\n      <b>3. Width of Central Maximum:</b><br>\n      The central maximum extends between first minima on either side (&plusmn;&theta;<sub>1</sub> = &plusmn;&lambda;/a):<br>\n      • <b>Angular Width:</b> <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b>2 &theta; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 &lambda;</span><span style=\"padding: 0 2px; display: inline-block;\">a</span></span></b></span> [radians].<br>\n      • <b>Linear Width (2x):</b> <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b>2x = 2 (D &theta;) = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 &lambda; D</span><span style=\"padding: 0 2px; display: inline-block;\">a</span></span> = 2 &beta;</b></span>.<br>\n      The central maximum is twice as wide as any secondary diffraction fringe and contains over 85% of total light energy!\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q91: Explain the phenomenon of Total Internal Reflection. Derive the formula for critical angle and describe its applications in optical fibers and prisms.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Phenomenon:</b> When light travels from denser medium (&mu;<sub>1</sub>) to rarer medium (&mu;<sub>2</sub>) at angle of incidence greater than critical angle (i &gt; i<sub>c</sub>), no refraction occurs; 100% of light energy is reflected back into denser medium.<br>\n      <b>2. Mathematical Derivation:</b> At critical angle i = i<sub>c</sub>, angle of refraction r = 90&deg;.<br>\n      Applying Snell's law: &mu;<sub>1</sub> sin(i<sub>c</sub>) = &mu;<sub>2</sub> sin(90&deg;) = &mu;<sub>2</sub>.<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 16.5px;\"><b>sin(i<sub>c</sub>) = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&mu;<sub>2</sub></span><span style=\"padding: 0 2px; display: inline-block;\">&mu;<sub>1</sub></span></span> &nbsp;&hArr;&nbsp; &mu; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">sin i<sub>c</sub></span></span></b></span> (for rarer medium air &mu;<sub>2</sub> = 1).<br>\n      <b>3. Applications:</b><br>\n      • <b>Totally Reflecting Prisms:</b> Right-angled isosceles prisms (45&deg;-90&deg;-45&deg;) bend light through 90&deg; or 180&deg; or invert images without loss of brightness (used in binoculars and periscopes).<br>\n      • <b>Optical Fibers:</b> Light entering high-index glass core undergoes continuous internal reflections, enabling high-bandwidth fiber optic internet and medical endoscopes.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q92: Derive the equivalent focal length and power of two thin coaxial lenses in contact.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Ray Tracing:</b> Consider two thin lenses L<sub>1</sub> (f<sub>1</sub>) and L<sub>2</sub> (f<sub>2</sub>) in contact. Object O is placed at distance u on principal axis. Lens L<sub>1</sub> forms intermediate image I' at distance v':<br>\n      <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">v'</span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>1</sub></span></span>. &nbsp;&nbsp; ...(1)<br>\n      <b>2. Second Lens:</b> Intermediate image I' acts as virtual object for lens L<sub>2</sub>, which forms final image I at distance v:<br>\n      <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">v'</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>2</sub></span></span>. &nbsp;&nbsp; ...(2)<br>\n      <b>3. Summing Equations:</b> Adding (1) and (2):<br>\n      <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">v</span></span> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">u</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>1</sub></span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>2</sub></span></span>. &nbsp;&nbsp; ...(3)<br>\n      <b>4. Equivalent Lens:</b> If single equivalent lens has focal length F: 1/v - 1/u = 1/F.<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">F</span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>1</sub></span></span> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>2</sub></span></span></b></span>.<br>\n      In terms of power (P = 1/f): <span style=\"color: #00E5FF; font-family: monospace; font-size: 17px;\"><b>P = P<sub>1</sub> + P<sub>2</sub></b></span>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q93: Discuss chromatic and spherical aberrations in lenses and explain how they are eliminated in optical devices.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Chromatic Aberration:</b> Arises because refractive index of glass varies with wavelength (&mu;<sub>v</sub> &gt; &mu;<sub>r</sub>). Violet focuses closer to lens than red, creating colored blurry halos.<br>\n      • <i>Correction:</i> Achromatic doublet combining a convex crown lens and concave flint lens such that &omega;<sub>1</sub>/f<sub>1</sub> + &omega;<sub>2</sub>/f<sub>2</sub> = 0, or by using reflecting mirrors.<br>\n      <b>2. Spherical Aberration:</b> Arises because marginal rays (outer aperture) bend more sharply than paraxial rays (central aperture), creating longitudinal blurring along axis.<br>\n      • <i>Correction:</i> Using stops/diaphragms to block marginal rays, parabolic surfaces, or combining positive and negative lenses separated by distance d = f<sub>1</sub> - f<sub>2</sub>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q94: State the principle, construction, and working of a reflecting Cassegrain telescope with mathematical magnifying power.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Principle:</b> Uses a large concave paraboloidal primary mirror to collect light and a secondary convex hyperboloidal mirror to reflect focused rays through a central hole in primary mirror to eyepiece.<br>\n      <b>2. Magnification:</b><br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17px;\"><b>m = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f<sub>o</sub></span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">R / 2</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span></b></span>.<br>\n      <b>3. Major Merits:</b><br>\n      • Total absence of chromatic aberration.<br>\n      • Large mirror aperture (several meters) provides immense resolving power.<br>\n      • Compact folded tube length compared to long refractor tubes.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q95: Explain the theory of interference of light. Derive expressions for resultant amplitude and intensity due to superposition of two waves y_1 = a_1 sin(&omega;t) and y_2 = a_2 sin(&omega;t + &phi;).</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Superposition:</b> Resultant displacement y = y<sub>1</sub> + y<sub>2</sub> = a<sub>1</sub> sin(&omega;t) + a<sub>2</sub> sin(&omega;t + &phi;)<br>\n      = a<sub>1</sub> sin(&omega;t) + a<sub>2</sub> [sin(&omega;t) cos &phi; + cos(&omega;t) sin &phi;]<br>\n      = (a<sub>1</sub> + a<sub>2</sub> cos &phi;) sin(&omega;t) + (a<sub>2</sub> sin &phi;) cos(&omega;t).<br>\n      Let R cos &theta; = a<sub>1</sub> + a<sub>2</sub> cos &phi; and R sin &theta; = a<sub>2</sub> sin &phi;:<br>\n      y = R sin(&omega;t + &theta;).<br>\n      <b>2. Resultant Amplitude R:</b> Squaring and adding:<br>\n      R<sup>2</sup> = (a<sub>1</sub> + a<sub>2</sub> cos &phi;)<sup>2</sup> + (a<sub>2</sub> sin &phi;)<sup>2</sup> = a<sub>1</sub><sup>2</sup> + a<sub>2</sub><sup>2</sup> + 2 a<sub>1</sub> a<sub>2</sub> cos &phi;.<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 16.5px;\"><b>R = &radic;[ a<sub>1</sub><sup>2</sup> + a<sub>2</sub><sup>2</sup> + 2 a<sub>1</sub> a<sub>2</sub> cos &phi; ]</b></span>.<br>\n      <b>3. Resultant Intensity (I &prop; R<sup>2</sup>):</b><br>\n      <span style=\"color: #00E5FF; font-family: monospace; font-size: 16.5px;\"><b>I = I<sub>1</sub> + I<sub>2</sub> + 2 &radic;(I<sub>1</sub> I<sub>2</sub>) cos &phi;</b></span>.<br>\n      For identical slits (I<sub>1</sub> = I<sub>2</sub> = I<sub>0</sub>): <b>I = 4 I<sub>0</sub> cos<sup>2</sup>(&phi;/2)</b>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q96: Discuss the conditions for sustained interference of light waves and explain why intensity is conserved during interference.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Sustained Interference Conditions:</b><br>\n      • Sources must be <b>coherent</b> (&Delta;&phi; constant over time).<br>\n      • Light must be <b>monochromatic</b> (single &lambda;).<br>\n      • Slit separation d must be small (~mm) and distance to screen D large.<br>\n      • Source slits must be narrow and have equal amplitudes (a<sub>1</sub> = a<sub>2</sub>) for pitch dark minima.<br>\n      <b>2. Conservation of Energy:</b><br>\n      At maxima: I<sub>max</sub> = (a<sub>1</sub> + a<sub>2</sub>)<sup>2</sup> = a<sub>1</sub><sup>2</sup> + a<sub>2</sub><sup>2</sup> + 2a<sub>1</sub>a<sub>2</sub>.<br>\n      At minima: I<sub>min</sub> = (a<sub>1</sub> - a<sub>2</sub>)<sup>2</sup> = a<sub>1</sub><sup>2</sup> + a<sub>2</sub><sup>2</sup> - 2a<sub>1</sub>a<sub>2</sub>.<br>\n      Average Intensity: I<sub>avg</sub> = (I<sub>max</sub> + I<sub>min</sub>)/2 = a<sub>1</sub><sup>2</sup> + a<sub>2</sub><sup>2</sup> = I<sub>1</sub> + I<sub>2</sub>.<br>\n      Light energy is not created or destroyed; it is simply <b>redistributed from dark minima to bright maxima</b> in strict compliance with the Law of Conservation of Energy!\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q97: Explain the difference between interference and diffraction patterns with detailed intensity distribution graphs and formulas.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Fundamental Differences:</b><br>\n      • <i>Origin:</i> Interference is superposition of 2 separate wavefronts; Diffraction is superposition of secondary wavelets from same wavefront.<br>\n      • <i>Fringe Width:</i> In YDSE, all fringes have equal width &beta; = &lambda;D/d. In single slit diffraction, central maximum is twice as wide (2&lambda;D/a) as secondary fringes (&lambda;D/a).<br>\n      • <i>Intensity Distribution:</i> In interference, all bright fringes have equal uniform intensity (4I<sub>0</sub>). In diffraction, central maximum has peak intensity I<sub>0</sub>, while secondary maxima fade extremely rapidly: I<sub>1</sub> &approx; I<sub>0</sub>/22, I<sub>2</sub> &approx; I<sub>0</sub>/61.<br>\n      • <i>Contrast:</i> Interference minima are completely pitch dark (zero intensity); diffraction minima are not completely black.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q98: A compound microscope consists of an objective of focal length 2.0 cm and eyepiece of focal length 6.25 cm separated by 15 cm. How far from the objective should an object be placed to form final image at (a) Least distance of distinct vision D = 25 cm, (b) Infinity? Find magnifying power in each case.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      Given: f<sub>o</sub> = +2.0 cm, f<sub>e</sub> = +6.25 cm, tube length L = 15 cm.<br>\n      <b>Case (a): Image at D = 25 cm (v<sub>e</sub> = -25 cm):</b><br>\n      1/u<sub>e</sub> = 1/v<sub>e</sub> - 1/f<sub>e</sub> = 1/(-25) - 1/6.25 = -1/25 - 4/25 = -5/25 = -1/5 &rArr; |u<sub>e</sub>| = 5 cm.<br>\n      Image distance from objective: v<sub>o</sub> = L - |u<sub>e</sub>| = 15 - 5 = 10 cm.<br>\n      1/u<sub>o</sub> = 1/v<sub>o</sub> - 1/f<sub>o</sub> = 1/10 - 1/2 = (1 - 5)/10 = -4/10 = -2/5 &rArr; <b>u<sub>o</sub> = -2.5 cm</b>.<br>\n      Magnification: <b>m = (v<sub>o</sub> / |u<sub>o</sub>|)(1 + D/f<sub>e</sub>) = (10 / 2.5)(1 + 25/6.25) = 4 &times; (1 + 4) = 4 &times; 5 = 20</b>.<br>\n      <b>Case (b): Image at Infinity:</b> |u<sub>e</sub>| = f<sub>e</sub> = 6.25 cm.<br>\n      v<sub>o</sub> = L - f<sub>e</sub> = 15 - 6.25 = 8.75 cm.<br>\n      1/u<sub>o</sub> = 1/v<sub>o</sub> - 1/f<sub>o</sub> = 1/8.75 - 1/2 = 1/(35/4) - 1/2 = 4/35 - 1/2 = (8 - 35)/70 = -27/70.<br>\n      &rArr; <b>u<sub>o</sub> = -70/27 &approx; -2.59 cm</b>.<br>\n      Magnification: <b>m = (v<sub>o</sub> / |u<sub>o</sub>|)(D / f<sub>e</sub>) = (8.75 / 2.59)(25 / 6.25) = 3.38 &times; 4 = 13.5</b>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q99: Describe the construction and working of an Astronomical Refracting Telescope. Derive magnifying power when final image is formed at near point D = 25 cm.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      <b>1. Construction:</b> Objective lens has large focal length f<sub>o</sub> and large aperture. Eyepiece has short focal length f<sub>e</sub> and small aperture.<br>\n      <b>2. Derivation for Image at D:</b><br>\n      Angular Magnification: m = &beta; / &alpha; = (A'B' / -u<sub>e</sub>) / (A'B' / f<sub>o</sub>) = - f<sub>o</sub> / u<sub>e</sub>.<br>\n      For eyepiece: 1/v<sub>e</sub> - 1/u<sub>e</sub> = 1/f<sub>e</sub>.<br>\n      Since v<sub>e</sub> = -D: -1/D - 1/u<sub>e</sub> = 1/f<sub>e</sub> &rArr; -1/u<sub>e</sub> = 1/f<sub>e</sub> + 1/D = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span> [ 1 + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f<sub>e</sub></span><span style=\"padding: 0 2px; display: inline-block;\">D</span></span> ].<br>\n      Substituting into magnification expression:<br>\n      <span style=\"color: #76FF03; font-family: monospace; font-size: 17.5px;\"><b>m = - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f<sub>o</sub></span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub></span></span> [ 1 + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f<sub>e</sub></span><span style=\"padding: 0 2px; display: inline-block;\">D</span></span> ]</b></span>.<br>\n      Tube Length: <b>L = f<sub>o</sub> + |u<sub>e</sub>| = f<sub>o</sub> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\"><span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">f<sub>e</sub> D</span><span style=\"padding: 0 2px; display: inline-block;\">f<sub>e</sub> + D</span></span></b>.\n    \n    </div>\n  </div>\n  <div style=\"background: rgba(15, 23, 42, 0.7); border: 1.2px solid rgba(255, 82, 82, 0.3); border-radius: 8px; padding: 14px 18px; margin: 16px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 16px; font-weight: bold;\">Q100: In YDSE, light of wavelength 600 nm is used. In the central fringe region, the intensity is I_0. Find the intensity at a point on the screen where the path difference is (i) &lambda;/6, (ii) &lambda;/4, (iii) &lambda;/3, (iv) &lambda;/2.</h3>\n    <div style=\"color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      \n      General Intensity Formula for two identical slits: <b>I = I<sub>0</sub> cos<sup>2</sup>(&phi;/2)</b>, where &phi; = (2&pi;/&lambda;) &Delta;x.<br>\n      <b>(i) For &Delta;x = &lambda;/6:</b><br>\n      &phi; = (2&pi;/&lambda;)(&lambda;/6) = &pi;/3 = 60&deg; &rArr; &phi;/2 = 30&deg;.<br>\n      I = I<sub>0</sub> cos<sup>2</sup>(30&deg;) = I<sub>0</sub> (&radic;3/2)<sup>2</sup> = <b>(3/4) I<sub>0</sub> = 0.75 I<sub>0</sub></b>.<br>\n      <b>(ii) For &Delta;x = &lambda;/4:</b><br>\n      &phi; = (2&pi;/&lambda;)(&lambda;/4) = &pi;/2 = 90&deg; &rArr; &phi;/2 = 45&deg;.<br>\n      I = I<sub>0</sub> cos<sup>2</sup>(45&deg;) = I<sub>0</sub> (1/&radic;2)<sup>2</sup> = <b>(1/2) I<sub>0</sub> = 0.50 I<sub>0</sub></b>.<br>\n      <b>(iii) For &Delta;x = &lambda;/3:</b><br>\n      &phi; = (2&pi;/&lambda;)(&lambda;/3) = 2&pi;/3 = 120&deg; &rArr; &phi;/2 = 60&deg;.<br>\n      I = I<sub>0</sub> cos<sup>2</sup>(60&deg;) = I<sub>0</sub> (1/2)<sup>2</sup> = <b>(1/4) I<sub>0</sub> = 0.25 I<sub>0</sub></b>.<br>\n      <b>(iv) For &Delta;x = &lambda;/2:</b><br>\n      &phi; = (2&pi;/&lambda;)(&lambda;/2) = &pi; = 180&deg; &rArr; &phi;/2 = 90&deg;.<br>\n      I = I<sub>0</sub> cos<sup>2</sup>(90&deg;) = I<sub>0</sub> (0) = <b>0 (Complete destructive darkness)</b>.\n    \n    </div>\n  </div>\n</div>";

